func TbWordsRaw(wd *port.Cells, et *port.Cells, tw *port.Cells, from int32, num int32, raw *port.Cells, order *port.Cells, keepLeaders int32) int32 {
	// The words tw[first..first+count) as code points into `raw`: a space between two words, none after a
	// soft hyphen (which goes). `raw` is emptied first.
	var k int32 = 0
	var j int32 = 0
	var started int32 = 0
	var v int32 = 0
	var line int32 = -1
	// D655: table fitting sorts by baseline and x. Within each contiguous parser line, word ids are already bidi-logical. Restore that order in scratch once, without reversing characters or rows. Unknown line ids keep their supplied order.
	port.CellsDrop(order, 0)
	for k < num {
		port.CellsPush(order, port.CellsAt(tw, from+k))
		k += 1
	}
	k = 1
	for k < num {
		v = port.CellsAt(order, k)
		line = evidence.WdGet(wd, v, evidence.HdLine())
		j = k
		if line >= 0 {
			for (j > 0) && (port.CellsAt(order, j-1) > v) && (evidence.WdGet(wd, port.CellsAt(order, j-1), evidence.HdLine()) == line) {
				port.CellsSet(order, j, port.CellsAt(order, j-1))
				j -= 1
			}
		}
		port.CellsSet(order, j, v)
		k += 1
	}
	k = 0
	port.CellsDrop(raw, 0)
	for k < num {
		var w int32 = port.CellsAt(order, k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		if (ts >= 0) && (tl > 0) {
			if started == 1 {
				var n int32 = port.CellsLen(raw)
				if (n > 0) && (port.CellsAt(raw, n-1) == 173) {
					port.CellsDrop(raw, n-1)
				} else {
					port.CellsPush(raw, 32)
				}
			}
			started = 1
			j = 0
			for j < tl {
				port.CellsPush(raw, port.CellsAt(et, ts+j))
				j += 1
			}
		}
		k += 1
	}
	if keepLeaders != 0 {
		return 0
	}
	var read int32 = 0
	var write int32 = 0
	var end int32 = 0
	var dots int32 = 0
	for read < port.CellsLen(raw) {
		end = read
		dots = 0
		if port.CellsAt(raw, read) == 46 {
			for (end < port.CellsLen(raw)) && ((port.CellsAt(raw, end) == 46) || (port.CellsAt(raw, end) == 32)) {
				if port.CellsAt(raw, end) == 46 {
					dots += 1
				}
				end += 1
			}
		}
		if dots >= 4 {
			for (write > 0) && (port.CellsAt(raw, write-1) == 32) {
				write -= 1
			}
			if (write > 0) && (end < port.CellsLen(raw)) {
				port.CellsSet(raw, write, 32)
				write += 1
			}
			read = end
		} else {
			port.CellsSet(raw, write, port.CellsAt(raw, read))
			write += 1
			read += 1
		}
	}
	port.CellsDrop(raw, write)
	return 0
}

func tbEmitCell(tb *port.Cells, k int32, c int32, row int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells) int32 {
	var cb int32 = c * tcs
	var page int32 = port.CellsAt(tb, k*tagtable.Tbs)
	var n int32 = model.NodeNew(nodes, model.NkCell(), row)
	var wc int32 = port.CellsAt(tc, cb+9)
	model.NodeSetConf(nodes, n, 600)
	model.NodeAddSrc(nodes, n, model.SrText())
	model.NodeAddSrc(nodes, n, model.SrInfer())
	if port.CellsAt(tc, cb+10) > 0 {
		model.NodeSetSub(nodes, n, port.CellsAt(tc, cb+10))
	}
	if port.CellsAt(tc, cb+2) > 1 {
		model.NodeSetAttrInt(nodes, attrs, n, model.FkRowspan(), port.CellsAt(tc, cb+2))
	}
	if port.CellsAt(tc, cb+3) > 1 {
		model.NodeSetAttrInt(nodes, attrs, n, model.FkColspan(), port.CellsAt(tc, cb+3))
	}
	if port.CellsAt(tc, cb+11) > 0 {
		model.NodeSetAlign(nodes, attrs, n, port.CellsAt(tc, cb+11))
	}
	model.NodeAddRegion(nodes, regions, n, page, port.CellsAt(tc, cb+4), port.CellsAt(tc, cb+5), port.CellsAt(tc, cb+6), port.CellsAt(tc, cb+7))
	if wc == 0 {
		model.NodeSetAux(nodes, n, 1)
	} else {
		TbWordsRaw(wd, et, tw, port.CellsAt(tc, cb+8), wc, raw, tmp, port.CellsAt(tb, (k*tagtable.Tbs)+31)&tbWidgetPage)
		var t0 int32 = port.CellsLen(text)
		normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
		model.NodeSetText(nodes, n, t0, port.CellsLen(text)-t0)
	}
	return 0
}

func tbPutWord(text *port.Cells, wd *port.Cells, et *port.Cells, w int32) int32 {
	// The word's code points appended to the text arena without its trailing full stops and colons.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var j int32 = 0
	for (tl > 1) && ((port.CellsAt(et, ts+(tl-1)) == 46) || (port.CellsAt(et, ts+(tl-1)) == 58)) {
		tl -= 1
	}
	for j < tl {
		model.TextAppendCp(text, port.CellsAt(et, ts+j))
		j += 1
	}
	return 0
}

func tbSeparator(wd *port.Cells, et *port.Cells, w int32) bool {
	// A word that is only a separator between a label and its text: . : - en dash em dash.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	if tl != 1 {
		return 0 == 1
	}
	var cp int32 = port.CellsAt(et, ts)
	return (cp == 46) || ((cp == 58) || ((cp == 45) || ((cp == 8211) || (cp == 8212))))
}

func tbEmitCaption(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, ln *port.Cells, tq *port.Cells, t int32, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells) int32 {
	// The caption of table k as the table's first child: `label` (the keyword and the number), the rest as its text.
	var b int32 = k * tagtable.Tbs
	var qn int32 = port.CellsAt(tb, b+15)
	var qf int32 = port.CellsAt(tb, b+14)
	if qn == 0 {
		return 0
	}
	var capn int32 = model.NodeNew(nodes, model.NkCaption(), t)
	var l0 int32 = port.CellsAt(tq, qf)
	var w0 int32 = evidence.LnGet(ln, l0, evidence.LhFirst())
	var s int32 = port.CellsLen(text)
	var x0 int32 = 2000000000
	var y0 int32 = 2000000000
	var x1 int32 = -2000000000
	var y1 int32 = -2000000000
	var q int32 = 0
	var gi int32 = 0
	var j int32 = 0
	var started int32 = 0
	model.NodeSetConf(nodes, capn, 600)
	model.NodeAddSrc(nodes, capn, model.SrText())
	model.NodeAddSrc(nodes, capn, model.SrInfer())
	tbPutWord(text, wd, et, w0)
	model.TextAppendCp(text, 32)
	tbPutWord(text, wd, et, w0+1)
	model.NodeSetAttrText(nodes, attrs, capn, model.FkLabel(), s, port.CellsLen(text)-s)
	port.CellsDrop(raw, 0)
	for q < qn {
		var l int32 = port.CellsAt(tq, qf+q)
		var lf int32 = evidence.LnGet(ln, l, evidence.LhFirst())
		var lc int32 = evidence.LnGet(ln, l, evidence.LhCount())
		if evidence.LnGet(ln, l, evidence.LhX0()) < x0 {
			x0 = evidence.LnGet(ln, l, evidence.LhX0())
		}
		if evidence.LnGet(ln, l, evidence.LhY0()) < y0 {
			y0 = evidence.LnGet(ln, l, evidence.LhY0())
		}
		if evidence.LnGet(ln, l, evidence.LhX1()) > x1 {
			x1 = evidence.LnGet(ln, l, evidence.LhX1())
		}
		if evidence.LnGet(ln, l, evidence.LhY1()) > y1 {
			y1 = evidence.LnGet(ln, l, evidence.LhY1())
		}
		j = 0
		for j < lc {
			var w int32 = lf + j
			var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
			var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
			if (gi >= 2) && (tl > 0) {
				if !((started == 0) && tbSeparator(wd, et, w)) {
					if started == 1 {
						port.CellsPush(raw, 32)
					}
					started = 1
					var m int32 = 0
					for m < tl {
						port.CellsPush(raw, port.CellsAt(et, ts+m))
						m += 1
					}
				}
			}
			gi += 1
			j += 1
		}
		q += 1
	}
	var t0 int32 = port.CellsLen(text)
	normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
	model.NodeSetText(nodes, capn, t0, port.CellsLen(text)-t0)
	model.NodeAddRegion(nodes, regions, capn, port.CellsAt(tb, b), x0, y0, x1, y1)
	return capn
}

func TbCount(tb *port.Cells) int32 {
	return tbRowsOf(tb, tagtable.Tbs)
}

func TbPage(tb *port.Cells, k int32) int32 {
	return port.CellsAt(tb, k*tagtable.Tbs)
}

func TbTop(tb *port.Cells, k int32) int32 {
	return port.CellsAt(tb, (k*tagtable.Tbs)+2)
}

func TbDue(tb *port.Cells, k int32, page int32, ymid2 int32) bool {
	// Is table k on this page, and its top at or above twice-the-y `ymid2` (a line's baseline sum).
	if k >= tbRowsOf(tb, tagtable.Tbs) {
		return 0 == 1
	}
	if port.CellsAt(tb, k*tagtable.Tbs) != page {
		return 0 == 1
	}
	return (2 * port.CellsAt(tb, (k*tagtable.Tbs)+2)) <= ymid2
}

func TbDueFor(tb *port.Cells, k int32, page int32, ymid2 int32, ln *port.Cells, l int32) bool {
	// P12.7 (smoke A N4): `tb-due`, with the line `l` the table would be written before (-1: no line, only `ymid2`). A line to the left of the table (it ends within 6 pt of its left edge) that begins in the
	// table's own height is the label of what the table holds (a form's column of boxes and line numbers beside its rows): the field comes after its label, so such a line is written before the table.
	if !TbDue(tb, k, page, ymid2) {
		return 0 == 1
	}
	if l < 0 {
		return 1 == 1
	}
	var b int32 = k * tagtable.Tbs
	if (evidence.LnGet(ln, l, evidence.LhX1()) <= (port.CellsAt(tb, b+1) + 600)) && ((evidence.LnGet(ln, l, evidence.LhY0()) >= (port.CellsAt(tb, b+2) - 100)) && (evidence.LnGet(ln, l, evidence.LhY0()) <= port.CellsAt(tb, b+4))) {
		return 0 == 1
	}
	return 1 == 1
}

func TbSkip(tb *port.Cells, k int32, page int32) int32 {
	// The first table at or after k that is on a page at or after `page`.
	var i int32 = k
	for (i < tbRowsOf(tb, tagtable.Tbs)) && (port.CellsAt(tb, i*tagtable.Tbs) < page) {
		i += 1
	}
	return i
}

func tbEmitDropped(tb *port.Cells, f int32, r int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells, ledger *port.Cells) int32 {
	// A header row of fragment f that repeats the first fragment's (P5.4): into the ledger as `duplicate-header-row`,
	// its box, and its cells' text joined by a space.
	var b int32 = f * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var x0 int32 = 2000000000
	var y0 int32 = 2000000000
	var x1 int32 = -2000000000
	var y1 int32 = -2000000000
	var any int32 = 0
	var s int32 = port.CellsLen(text)
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			if port.CellsAt(tc, (c*tcs)+4) < x0 {
				x0 = port.CellsAt(tc, (c*tcs)+4)
			}
			if port.CellsAt(tc, (c*tcs)+5) < y0 {
				y0 = port.CellsAt(tc, (c*tcs)+5)
			}
			if port.CellsAt(tc, (c*tcs)+6) > x1 {
				x1 = port.CellsAt(tc, (c*tcs)+6)
			}
			if port.CellsAt(tc, (c*tcs)+7) > y1 {
				y1 = port.CellsAt(tc, (c*tcs)+7)
			}
			if port.CellsAt(tc, (c*tcs)+9) > 0 {
				if any == 1 {
					model.TextAppendCp(text, 32)
				}
				any = 1
				TbWordsRaw(wd, et, tw, port.CellsAt(tc, (c*tcs)+8), port.CellsAt(tc, (c*tcs)+9), raw, tmp, port.CellsAt(tb, b+31)&tbWidgetPage)
				normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
			}
		}
		c += 1
	}
	var l int32 = model.LedgerAdd(ledger, model.DrDuplicateHeaderRow(), port.CellsAt(tb, b), x0, y0, x1, y1, 700, model.SrText()+model.SrInfer())
	model.LedgerSetText(ledger, l, s, port.CellsLen(text)-s)
	return 0
}

func tbEmitGap(tb *port.Cells, f int32, row int32, x int32, y0 int32, y1 int32, nodes *port.Cells, regions *port.Cells) int32 {
	// P12.2: an empty cell of row `row` of fragment f, a column of the table that the page of f has none for (`tb-widen`): a cell with no text and a
	// region of no width, at x.
	var n int32 = model.NodeNew(nodes, model.NkCell(), row)
	model.NodeSetConf(nodes, n, 600)
	model.NodeAddSrc(nodes, n, model.SrText())
	model.NodeAddSrc(nodes, n, model.SrInfer())
	model.NodeSetAux(nodes, n, 1)
	model.NodeAddRegion(nodes, regions, n, port.CellsAt(tb, f*tagtable.Tbs), x, y0, x, y1)
	return 0
}

func TbEmit(tb *port.Cells, k int32, parent int32, wd *port.Cells, et *port.Cells, ln *port.Cells, tc *port.Cells, tw *port.Cells, tq *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells, ledger *port.Cells) int32 {
	// Append table k to the Model under `parent` (the root, or the open section, D178): the table node, its caption, its row groups, rows
	// and cells, in document order; the fragments that follow it on later pages (`tb-link`) are its rows too, and
	// their repeated header rows go to the ledger. A table that is a later fragment of another is not written
	// (answers -1). Answers the table's node.
	if port.CellsAt(tb, (k*tagtable.Tbs)+21) != 0 {
		return -1
	}
	var b int32 = k * tagtable.Tbs
	var prof int32 = port.CellsAt(tb, b+5)
	var nhead int32 = port.CellsAt(tb, b+11)
	var t int32 = model.NodeNew(nodes, model.NkTable(), parent)
	var f int32 = k
	var g int32 = -1
	var role int32 = 0
	var row int32 = -1
	var r int32 = 0
	var ci int32 = 0
	var nc int32 = 0
	var gx int32 = 0
	var gy0 int32 = 0
	var gy1 int32 = 0
	var want int32 = 0
	model.NodeSetConf(nodes, t, 600)
	model.NodeAddSrc(nodes, t, model.SrText())
	model.NodeAddSrc(nodes, t, model.SrInfer())
	if prof == pfRuled {
		model.NodeAddSrc(nodes, t, model.SrVector())
	}
	if (prof == pfStruct) || ((port.CellsAt(tb, b+24) & 1) != 0) {
		model.NodeAddSrc(nodes, t, model.SrStruct())
	}
	if (port.CellsAt(tb, b+24) & 2) != 0 {
		model.NodeAddFlag(nodes, t, model.FlTagSpanConflict())
	}
	if (port.CellsAt(tb, b+24) & 4) != 0 {
		model.NodeAddFlag(nodes, t, model.FlStructDisagree())
	}
	var s int32 = port.CellsLen(text)
	tbPutProfile(text, prof)
	model.NodeSetAttrText(nodes, attrs, t, model.FkProfile(), s, port.CellsLen(text)-s)
	model.NodeSetAttrInt(nodes, attrs, t, model.FkColumns(), port.CellsAt(tb, b+8))
	if port.CellsAt(tb, b+18) > 1 {
		model.NodeSetAttrInt(nodes, attrs, t, model.FkContinued(), port.CellsAt(tb, b+18))
	}
	tbEmitCaption(tb, k, wd, et, ln, tq, t, nodes, attrs, regions, text, raw, tmp)
	for f >= 0 {
		var fb int32 = f * tagtable.Tbs
		var nrows int32 = port.CellsAt(tb, fb+7)
		var cfirst int32 = port.CellsAt(tb, fb+9)
		var cend int32 = cfirst + port.CellsAt(tb, fb+10)
		var nfoot int32 = port.CellsAt(tb, fb+12)
		var nxt int32 = port.CellsAt(tb, fb+19)
		var skip int32 = port.CellsAt(tb, fb+20)
		model.NodeAddRegion(nodes, regions, t, port.CellsAt(tb, fb), port.CellsAt(tb, fb+1), port.CellsAt(tb, fb+2), port.CellsAt(tb, fb+3), port.CellsAt(tb, fb+4))
		r = 0
		for r < skip {
			tbEmitDropped(tb, f, r, wd, et, tc, tw, text, raw, tmp, ledger)
			r += 1
		}
		ci = cfirst
		for (ci < cend) && (port.CellsAt(tc, ci*tcs) < skip) {
			ci += 1
		}
		for r < nrows {
			want = model.RlBody()
			if (f == k) && (r < nhead) {
				want = model.RlHead()
			}
			if (nxt == 0) && (r >= (nrows - nfoot)) {
				want = model.RlFoot()
			}
			if want != role {
				g = model.NodeNew(nodes, model.NkRowgroup(), t)
				model.NodeSetSub(nodes, g, want)
				model.NodeSetConf(nodes, g, 600)
				model.NodeAddSrc(nodes, g, model.SrInfer())
				role = want
			}
			row = model.NodeNew(nodes, model.NkRow(), g)
			model.NodeSetConf(nodes, row, 600)
			model.NodeAddSrc(nodes, row, model.SrInfer())
			nc = 0
			for (ci < cend) && (port.CellsAt(tc, ci*tcs) == r) {
				if (port.CellsAt(tc, (ci*tcs)+12) & 1) == 0 {
					if port.CellsAt(tb, fb+23) == 1 {
						for nc < port.CellsAt(tc, (ci*tcs)+1) {
							tbEmitGap(tb, f, row, port.CellsAt(tc, (ci*tcs)+4), port.CellsAt(tc, (ci*tcs)+5), port.CellsAt(tc, (ci*tcs)+7), nodes, regions)
							nc += 1
						}
						nc = port.CellsAt(tc, (ci*tcs)+1) + port.CellsAt(tc, (ci*tcs)+3)
						gx = port.CellsAt(tc, (ci*tcs)+6)
						gy0 = port.CellsAt(tc, (ci*tcs)+5)
						gy1 = port.CellsAt(tc, (ci*tcs)+7)
					}
					tbEmitCell(tb, f, ci, row, wd, et, tc, tw, nodes, attrs, regions, text, raw, tmp)
				}
				ci += 1
			}
			// P12.2: a page whose columns are a subset of the table's (`tb-widen`): its rows end with the cells of the columns it has none for.
			if port.CellsAt(tb, fb+23) == 1 {
				for nc < port.CellsAt(tb, fb+8) {
					tbEmitGap(tb, f, row, gx, gy0, gy1, nodes, regions)
					nc += 1
				}
			}
			r += 1
		}
		f = nxt - 1
	}
	return t
}

func tbUpright(wd *port.Cells, w int32) bool {
	var r int32 = evidence.WdGet(wd, w, evidence.HdRot())
	return (r < 100) || (r > 35900)
}

func tbClamp64(v int64) int32 {
	// A 64-bit value held to +-2e9 (hostile coordinates multiply past 2^31, P10.5 D387; the tilt's arithmetic is 64-bit for the same reason).
	if v > int64(2000000000) {
		return 2000000000
	}
	if v < int64(-2000000000) {
		return -2000000000
	}
	return int32(v)
}

func tbTilt(wd *port.Cells, wl *port.Cells, n int32) int32 {
	// The tilt of the page's baselines, parts per million (the rise of a baseline over its run, summed over the words
	// of wl[0, n) and divided by the runs: a word's own slope is a pixel or two over a few characters, noise, but the
	// sum of hundreds of them is the page's). 0 under 2000 ppm (about a tenth of a degree: a text layer, a flat scan)
	// and for a tilt past about 4.8 degrees, which is no tilt of a page (D391). 64-bit sums: a hostile layer's words
	// do not overflow it (D387's kind; D391 wrote it in 32 bits).
	var sdy int64 = int64(0)
	var sdx int64 = int64(0)
	var i int32 = 0
	for i < n {
		var w int32 = port.CellsAt(wl, i)
		var dx int64 = int64(evidence.WdGet(wd, w, evidence.HdBx1())) + (int64(evidence.WdGet(wd, w, evidence.HdBx0())) * int64(-1))
		var dy int64 = int64(evidence.WdGet(wd, w, evidence.HdBy1())) + (int64(evidence.WdGet(wd, w, evidence.HdBy0())) * int64(-1))
		if (dx > int64(0)) && (((int64(12) * dy) <= dx) && ((int64(-12) * dy) <= dx)) {
			sdy = sdy + dy
			sdx = sdx + dx
		}
		i += 1
	}
	if (sdx / int64(1000)) >= int64(1) {
		var ppm int64 = (sdy * int64(1000)) / (sdx / int64(1000))
		if (ppm >= int64(2000)) && (ppm <= int64(83000)) {
			return int32(ppm)
		}
		if (ppm <= int64(-2000)) && (ppm >= int64(-83000)) {
			return int32(ppm)
		}
	}
	return 0
}

func tbBkey(wd *port.Cells, w int32, ppm int32) int32 {
	// The word's right baseline height carried back to the page's left edge along the page's tilt `ppm`: what a row's
	// words share on a tilted scan, where a row's left and right words differ by several sizes of baseline over a table's
	// width and the chain of rows below would cut a row where a column is empty. ppm 0 answers `by1`, as before.
	// 64-bit and clamped: a hostile coordinate times the tilt does not overflow (D387's kind).
	if ppm == 0 {
		return evidence.WdGet(wd, w, evidence.HdBy1())
	}
	var f int32 = w
	var steps int32 = 0
	var lin int32 = evidence.WdGet(wd, w, evidence.HdLine())
	// The anchor is the first word of the word's line (at most 64 words back): every word of a line gets one key,
	// the line's start carried along the page's tilt, and not its own point on a baseline whose slope is a pixel's noise
	// (a short line's slope is not the page's, and the error grows with the distance from the line's start; D459).
	if lin >= 0 {
		for (f > 0) && ((steps < 64) && (evidence.WdGet(wd, f-1, evidence.HdLine()) == lin)) {
			f -= 1
			steps += 1
		}
	}
	var sh int64 = (int64(evidence.WdGet(wd, f, evidence.HdBx0())/100) * int64(ppm)) / int64(10000)
	return tbClamp64(int64(evidence.WdGet(wd, f, evidence.HdBy0())) + (sh * int64(-1)))
}

func tbWless(wd *port.Cells, a int32, b int32, mode int32, ppm int32) bool {
	// Does word a come before word b: mode 0 by baseline then x, mode 1 by x; then by index.
	if mode == 0 {
		var ya int32 = tbBkey(wd, a, ppm)
		var yb int32 = tbBkey(wd, b, ppm)
		if ya != yb {
			return ya < yb
		}
	}
	var xa int32 = evidence.WdGet(wd, a, evidence.HdX0())
	var xb int32 = evidence.WdGet(wd, b, evidence.HdX0())
	if xa != xb {
		return xa < xb
	}
	return a < b
}

func tbSortWords(wl *port.Cells, wd *port.Cells, from int32, to int32, mode int32, ppm int32) int32 {
	// Shell sort of wl[from, to) by `tb-wless`.
	var n int32 = to - from
	var h int32 = 1
	var i int32 = 0
	var j int32 = 0
	var v int32 = 0
	var u int32 = 0
	var more int32 = 1
	for h < (n / 3) {
		h = (h * 3) + 1
	}
	for h >= 1 {
		i = h
		for i < n {
			v = port.CellsAt(wl, from+i)
			j = i
			more = 1
			for (j >= h) && (more == 1) {
				u = port.CellsAt(wl, from+(j-h))
				if tbWless(wd, v, u, mode, ppm) {
					port.CellsSet(wl, from+j, u)
					j -= h
				} else {
					more = 0
				}
			}
			port.CellsSet(wl, from+j, v)
			i += 1
		}
		h = (h - 1) / 3
	}
	return 0
}

func tbWordDigit(wd *port.Cells, et *port.Cells, w int32) bool {
	// Does the word have a digit.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var j int32 = 0
	for j < tl {
		if (port.CellsAt(et, ts+j) >= 48) && (port.CellsAt(et, ts+j) <= 57) {
			return 1 == 1
		}
		j += 1
	}
	return 0 == 1
}

func tbLoneCp(wd *port.Cells, et *port.Cells, w int32, cp int32) bool {
	// Is the word the one character cp.
	return (evidence.WdGet(wd, w, evidence.HdTlen()) == 1) && (port.CellsAt(et, evidence.WdGet(wd, w, evidence.HdTstart())) == cp)
}

func tbCurrencyLead(wd *port.Cells, et *port.Cells, a int32, b int32) bool {
	// P12.2 (smoke review, issue 19): is the word a a currency sign of a word of its own and b the amount after it (a statement sets the dollar sign
	// at the left of its column and the figure at the right of it: the sign is the amount's, not a cell, nor the end of the cell before it).
	return (tbLoneCp(wd, et, a, 36) || (tbLoneCp(wd, et, a, 8364) || (tbLoneCp(wd, et, a, 163) || tbLoneCp(wd, et, a, 165)))) && tbWordDigit(wd, et, b)
}

func tbCurrencySign(wd *port.Cells, et *port.Cells, w int32) bool {
	return tbLoneCp(wd, et, w, 36) || (tbLoneCp(wd, et, w, 8364) || (tbLoneCp(wd, et, w, 163) || tbLoneCp(wd, et, w, 165)))
}

func tbCurrencyStyle(wd *port.Cells, et *port.Cells, wl *port.Cells, first int32, n int32) int32 {
	// P12.2: where the currency sign goes in the amounts of the row of the words first..first+n of `wl`, left to right: 2 after them, when the row ends with a
	// currency sign of a word of its own (`1 895,80 $  11 732,54 $`, the French way), else 1 before them, when a sign of a word of its own is followed by a
	// word with a digit (`$ 33,672  $ 32,260`), else 0.
	var k int32 = 0
	if (n > 1) && tbCurrencySign(wd, et, port.CellsAt(wl, first+(n-1))) {
		return 2
	}
	for (k + 1) < n {
		if tbCurrencyLead(wd, et, port.CellsAt(wl, first+k), port.CellsAt(wl, (first+k)+1)) {
			return 1
		}
		k += 1
	}
	return 0
}

func tbGlued(wd *port.Cells, et *port.Cells, a int32, b int32, style int32) bool {
	// P12.2 (smoke review, issue 19): do the words a and b, one after the other on a baseline, belong in one chunk whatever the gap between them: a
	// currency sign and its amount (`tb-currency-lead`, when `style` is 1: the sign goes before the amount; the amount and its sign when it is 2), and
	// a full stop of a word of its own after a word (a leader's dots: they are no cells of their own).
	if (style == 1) && tbCurrencyLead(wd, et, a, b) {
		return 1 == 1
	}
	if (style == 2) && (tbCurrencySign(wd, et, b) && tbWordDigit(wd, et, a)) {
		return 1 == 1
	}
	if tbLoneCp(wd, et, b, 46) {
		return 1 == 1
	}
	return 0 == 1
}

func tbFirstCx(wd *port.Cells, et *port.Cells, wl *port.Cells, ks int32, ke int32) int32 {
	// P12.2: the x that tells the column of the words ks..ke of `wl` (the words of one stretch of a row): the centre of the first, or of the second
	// when the first is a currency sign and the second its amount (`tb-currency-lead`: the sign sits where the column before ends).
	if (ks + 1) < ke {
		if tbCurrencyLead(wd, et, port.CellsAt(wl, ks), port.CellsAt(wl, ks+1)) {
			return (evidence.WdGet(wd, port.CellsAt(wl, ks+1), evidence.HdX0()) + evidence.WdGet(wd, port.CellsAt(wl, ks+1), evidence.HdX1())) / 2
		}
	}
	return (evidence.WdGet(wd, port.CellsAt(wl, ks), evidence.HdX0()) + evidence.WdGet(wd, port.CellsAt(wl, ks), evidence.HdX1())) / 2
}

func tbChainTol(wd *port.Cells, a int32, b int32, tol int32) int32 {
	// The baseline distance at which the word b still joins the row of the word a: `tol`, a third of the first word's size, but at
	// most a third of the smaller of the two sizes. A line's size is its box's height, and a box that took in the dark band of a
	// header (or a stamp) is several times the text's; its size must not let the line below join its row (D459).
	var sa int32 = tbMax(500, evidence.WdGet(wd, a, evidence.WfSize()))
	var sb int32 = tbMax(500, evidence.WdGet(wd, b, evidence.WfSize()))
	var t2 int32 = (3 * tbMin(sa, sb)) / 10
	if t2 < tol {
		return t2
	}
	return tol
}

func tbRows(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, rx0 int32, ry0 int32, rx1 int32, ry1 int32, wl *port.Cells, rw *port.Cells, sg *port.Cells) int32 {
	// The upright words w0..w1 of the page whose centre is in the box, as baseline rows and chunks (see the
	// head of this section; a chunk is not cut between words `tb-glued`, whatever the gap). Answers the number of rows.
	var w int32 = w0
	var i int32 = 0
	var j int32 = 0
	var ppm int32 = 0
	var n int32 = 0
	port.CellsDrop(wl, 0)
	port.CellsDrop(rw, 0)
	port.CellsDrop(sg, 0)
	for w < w1 {
		var cx int32 = (evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2
		var cy int32 = (evidence.WdGet(wd, w, evidence.HdY0()) + evidence.WdGet(wd, w, evidence.HdY1())) / 2
		if (evidence.WdGet(wd, w, evidence.HdTlen()) > 0) && tbUpright(wd, w) {
			if (cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1))) {
				port.CellsPush(wl, w)
			}
		}
		w += 1
	}
	n = port.CellsLen(wl)
	ppm = tbTilt(wd, wl, n)
	tbSortWords(wl, wd, 0, n, 0, ppm)
	i = 0
	for i < n {
		var w0i int32 = port.CellsAt(wl, i)
		var tol int32 = (3 * tbMax(500, evidence.WdGet(wd, w0i, evidence.WfSize()))) / 10
		// A row is a CHAIN of baselines: each word within a third of the size of the one before it in baseline
		// order (not of the first: a scan's rows slope, so one row's baselines spread over several points: OCR lines in the table stage, D213).
		j = i + 1
		for (j < n) && (tbAbs(tbBkey(wd, port.CellsAt(wl, j), ppm)-tbBkey(wd, port.CellsAt(wl, j-1), ppm)) <= tbChainTol(wd, port.CellsAt(wl, j-1), port.CellsAt(wl, j), tol)) {
			j += 1
		}
		tbSortWords(wl, wd, i, j, 1, ppm)
		var ri int32 = tbRowsOf(rw, rws)
		var sumy int64 = int64(0)
		var sums int64 = int64(0)
		var x0 int32 = 2000000000
		var x1 int32 = -2000000000
		var y0 int32 = 2000000000
		var y1 int32 = -2000000000
		var k int32 = i
		for k < j {
			var wk int32 = port.CellsAt(wl, k)
			sumy = sumy + int64(tbBkey(wd, wk, ppm))
			sums = sums + int64(tbMax(1, evidence.WdGet(wd, wk, evidence.WfSize())))
			if evidence.WdGet(wd, wk, evidence.HdX0()) < x0 {
				x0 = evidence.WdGet(wd, wk, evidence.HdX0())
			}
			if evidence.WdGet(wd, wk, evidence.HdX1()) > x1 {
				x1 = evidence.WdGet(wd, wk, evidence.HdX1())
			}
			if evidence.WdGet(wd, wk, evidence.HdY0()) < y0 {
				y0 = evidence.WdGet(wd, wk, evidence.HdY0())
			}
			if evidence.WdGet(wd, wk, evidence.HdY1()) > y1 {
				y1 = evidence.WdGet(wd, wk, evidence.HdY1())
			}
			k += 1
		}
		var cnt int32 = j - i
		var size int32 = int32(sums / int64(cnt))
		var thr int32 = (size * segNum) / segDen
		var sf int32 = tbRowsOf(sg, sgs)
		var sty int32 = tbCurrencyStyle(wd, et, wl, i, j-i)
		var cstart int32 = i
		var cmax int32 = evidence.WdGet(wd, port.CellsAt(wl, i), evidence.HdX1())
		port.CellsPush(rw, i)
		port.CellsPush(rw, cnt)
		port.CellsPush(rw, int32(sumy/int64(cnt)))
		port.CellsPush(rw, size)
		port.CellsPush(rw, x0)
		port.CellsPush(rw, x1)
		port.CellsPush(rw, y0)
		port.CellsPush(rw, y1)
		port.CellsPush(rw, sf)
		port.CellsPush(rw, 0)
		k = i + 1
		for k <= j {
			if (k == j) || ((sty == 1) && ((((k + 1) < j) && tbCurrencyLead(wd, et, port.CellsAt(wl, k), port.CellsAt(wl, k+1))) && tbWordDigit(wd, et, port.CellsAt(wl, k-1)))) || (((evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX0()) - cmax) > thr) && !tbGlued(wd, et, port.CellsAt(wl, k-1), port.CellsAt(wl, k), sty)) {
				port.CellsPush(sg, ri)
				port.CellsPush(sg, evidence.WdGet(wd, port.CellsAt(wl, cstart), evidence.HdX0()))
				port.CellsPush(sg, cmax)
				port.CellsPush(sg, cstart)
				port.CellsPush(sg, k-cstart)
				port.CellsPush(sg, 0)
				if k < j {
					cstart = k
					cmax = evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1())
				}
			}
			if k < j {
				if evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1()) > cmax {
					cmax = evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1())
				}
			}
			k += 1
		}
		port.CellsSet(rw, (ri*rws)+9, tbRowsOf(sg, sgs)-sf)
		i = j
	}
	return tbRowsOf(rw, rws)
}

func tbChannels(wd *port.Cells, et *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ra int32, rb int32, allow int32, minw int32, ch *port.Cells, st *port.Cells, en *port.Cells) int32 {
	// The channels of rows ra..rb: the stretches of the x axis, at least minw wide, that at most `allow` of the
	// tabular rows' words (rows of two chunks or more) cover. `st` and `en` are scratch. Answers how many.
	var r int32 = ra
	var k int32 = 0
	var sty int32 = 0
	var i int32 = 0
	var j int32 = 0
	var cov int32 = 0
	var prev int32 = 0
	var cs int32 = -1
	var ce int32 = 0
	port.CellsDrop(ch, 0)
	port.CellsDrop(st, 0)
	port.CellsDrop(en, 0)
	for r < rb {
		if port.CellsAt(rw, (r*rws)+9) >= 2 {
			k = 0
			sty = tbCurrencyStyle(wd, et, wl, port.CellsAt(rw, r*rws), port.CellsAt(rw, (r*rws)+1))
			for k < port.CellsAt(rw, (r*rws)+1) {
				var w int32 = port.CellsAt(wl, port.CellsAt(rw, r*rws)+k)
				// A dollar sign of a word of its own before its amount is the amount's (`tb-glued`): it covers nothing, its column is the amount's (set apart
				// from it as it is, it is in the channel or the label's column and no column of its own).
				if (sty != 1) || (((k + 1) == port.CellsAt(rw, (r*rws)+1)) || !tbCurrencyLead(wd, et, w, port.CellsAt(wl, (port.CellsAt(rw, r*rws)+k)+1))) {
					port.CellsPush(st, evidence.WdGet(wd, w, evidence.HdX0()))
					port.CellsPush(en, evidence.WdGet(wd, w, evidence.HdX1()))
				}
				// The gap between two words that `tb-glued` joins whatever it is, but a sign before its amount (a leader's dots, a sign after its amount) is
				// covered: it is no channel.
				if k > 0 {
					var wp int32 = port.CellsAt(wl, (port.CellsAt(rw, r*rws)+k)+-1)
					if tbGlued(wd, et, wp, w, sty) && (!tbCurrencyLead(wd, et, wp, w) && (evidence.WdGet(wd, w, evidence.HdX0()) > evidence.WdGet(wd, wp, evidence.HdX1()))) {
						port.CellsPush(st, evidence.WdGet(wd, wp, evidence.HdX1()))
						port.CellsPush(en, evidence.WdGet(wd, w, evidence.HdX0()))
					}
				}
				k += 1
			}
		}
		r += 1
	}
	tbSortNums(st)
	tbSortNums(en)
	var n int32 = port.CellsLen(st)
	if n == 0 {
		return 0
	}
	prev = port.CellsAt(st, 0)
	for (i < n) || (j < n) {
		var x int32 = 0
		if i < n {
			x = port.CellsAt(st, i)
		} else {
			x = port.CellsAt(en, j)
		}
		if (j < n) && (port.CellsAt(en, j) < x) {
			x = port.CellsAt(en, j)
		}
		if cov <= allow {
			if cs < 0 {
				cs = prev
			}
			ce = x
		} else {
			if cs >= 0 {
				if (ce - cs) >= minw {
					port.CellsPush(ch, cs)
					port.CellsPush(ch, ce)
				}
				cs = -1
			}
		}
		for (i < n) && (port.CellsAt(st, i) == x) {
			cov += 1
			i += 1
		}
		for (j < n) && (port.CellsAt(en, j) == x) {
			cov -= 1
			j += 1
		}
		prev = x
	}
	if (cs >= 0) && ((ce - cs) >= minw) {
		port.CellsPush(ch, cs)
		port.CellsPush(ch, ce)
	}
	return port.CellsLen(ch) / 2
}

func tbColOf(ch *port.Cells, x int32) int32 {
	// The column of x: how many channel midpoints are at or before it.
	var n int32 = port.CellsLen(ch) / 2
	var i int32 = 0
	var c int32 = 0
	for i < n {
		if ((port.CellsAt(ch, i*2) + port.CellsAt(ch, (i*2)+1)) / 2) <= x {
			c += 1
		}
		i += 1
	}
	return c
}

func tbWordCx(wd *port.Cells, w int32) int32 {
	return (evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2
}

func tbChunkA(wd *port.Cells, et *port.Cells, wl *port.Cells, sg *port.Cells, ch *port.Cells, s int32) int32 {
	// The first column of chunk s: the column of its first word's centre (`tb-first-cx`).
	return tbColOf(ch, tbFirstCx(wd, et, wl, port.CellsAt(sg, (s*sgs)+3), port.CellsAt(sg, (s*sgs)+3)+port.CellsAt(sg, (s*sgs)+4)))
}

func tbChunkB(wd *port.Cells, wl *port.Cells, sg *port.Cells, ch *port.Cells, s int32) int32 {
	// The last column of chunk s: the column of its last word's centre.
	return tbColOf(ch, tbWordCx(wd, port.CellsAt(wl, (port.CellsAt(sg, (s*sgs)+3)+port.CellsAt(sg, (s*sgs)+4))-1)))
}

func tbGapsOver(rw *port.Cells, ra int32, rb int32, pitch int32) bool {
	// P12.2 (smoke review, issue 6): does the table's pitch go over `pitch` by half again twice or more among the rows ra..rb: the gaps between the rows
	// of a table whose cells wrap (the lines of a cell are tight, the rows a line apart), at least two of them, not the one gap a table may have.
	var r int32 = ra + 1
	var n int32 = 0
	for r < rb {
		if (2 * (port.CellsAt(rw, (r*rws)+2) - port.CellsAt(rw, ((r-1)*rws)+2))) >= (3 * pitch) {
			n += 1
		}
		r += 1
	}
	return n >= 2
}

func tbRowMap(wd *port.Cells, et *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, ra int32, rb int32, ncols int32, rmap *port.Cells, occ *port.Cells) int32 {
	// The table row of each baseline row ra..rb (rmap[r - ra]): a baseline row goes on the row above when
	// it is a continuation of a wrapped cell: a tight line pitch (at most 1.35 of the size and 4/5 of the
	// mean pitch, or the pitch of a table whose rows are a gap apart, `tb-gaps-over`), no chunk with a span, and chunks only in columns the row above
	// had, at most half of them.
	// Answers the number of table rows.
	var r int32 = ra
	var rows int32 = -1
	var c int32 = 0
	var cont int32 = 0
	var occn int32 = 0
	var ok int32 = 1
	var s int32 = 0
	var mean int32 = 0
	if (rb - ra) > 1 {
		mean = (port.CellsAt(rw, ((rb-1)*rws)+2) - port.CellsAt(rw, (ra*rws)+2)) / ((rb - ra) - 1)
	}
	port.CellsDrop(rmap, 0)
	port.CellsDrop(occ, 0)
	for c < ncols {
		port.CellsPush(occ, 0)
		c += 1
	}
	for r < rb {
		cont = 0
		if (rows > -1) && (r > ra) {
			var pitch int32 = port.CellsAt(rw, (r*rws)+2) - port.CellsAt(rw, ((r-1)*rws)+2)
			var size int32 = port.CellsAt(rw, (r*rws)+3)
			var nchunks int32 = port.CellsAt(rw, (r*rws)+9)
			if ((pitch * 20) <= (size * 27)) && ((mean > 0) && (((pitch * 5) <= (mean * 4)) || tbGapsOver(rw, ra, rb, pitch))) {
				occn = 0
				c = 0
				for c < ncols {
					if port.CellsAt(occ, c) == 1 {
						occn += 1
					}
					c += 1
				}
				if (nchunks < occn) && ((nchunks * 2) <= occn) {
					ok = 1
					s = 0
					for s < nchunks {
						var si int32 = port.CellsAt(rw, (r*rws)+8) + s
						var a int32 = tbChunkA(wd, et, wl, sg, ch, si)
						var b int32 = tbChunkB(wd, wl, sg, ch, si)
						if a != b {
							ok = 0
						}
						if port.CellsAt(occ, a) != 1 {
							ok = 0
						}
						s += 1
					}
					cont = ok
				}
			}
		}
		if cont == 0 {
			rows += 1
			c = 0
			for c < ncols {
				port.CellsSet(occ, c, 0)
				c += 1
			}
		}
		s = 0
		for s < port.CellsAt(rw, (r*rws)+9) {
			var si int32 = port.CellsAt(rw, (r*rws)+8) + s
			var a int32 = tbChunkA(wd, et, wl, sg, ch, si)
			var b int32 = tbChunkB(wd, wl, sg, ch, si)
			c = a
			for c <= b {
				port.CellsSet(occ, c, 1)
				c += 1
			}
			s += 1
		}
		port.CellsPush(rmap, rows)
		r += 1
	}
	return rows + 1
}

func tbCut(ch *port.Cells, k int32, lo int32, hi int32) int32 {
	// The boundary before column k: lo for the first, else the midpoint of channel k-1; hi after the last.
	var n int32 = port.CellsLen(ch) / 2
	if k <= 0 {
		return lo
	}
	if k > n {
		return hi
	}
	return (port.CellsAt(ch, (k-1)*2) + port.CellsAt(ch, ((k-1)*2)+1)) / 2
}

func tbCutList(wd *port.Cells, wl *port.Cells, rw *port.Cells, rm *port.Cells, ra int32, rb int32, minx int32, maxx int32, cl *port.Cells) int32 {
	// D559: the x of every vertical rule of `rm` that is a column cut of the rows ra..rb, in `cl` (emptied first). A rule is one when it
	// lies inside the rows' extent minx..maxx, runs along three in five of the rows at least (two or more) and passes through no word of those
	// rows (a rule through a word is a strike or a frame, not the border between two cells). Answers how many.
	var nrl int32 = tbRowsOf(rm, rls)
	var n int32 = rb - ra
	var i int32 = 0
	var r int32 = 0
	var k int32 = 0
	var p int32 = 0
	var spanned int32 = 0
	var crossed int32 = 0
	var cy int32 = 0
	var w int32 = 0
	port.CellsDrop(cl, 0)
	if n < 2 {
		return 0
	}
	for i < nrl {
		if port.CellsAt(rm, i*rls) == 1 {
			p = port.CellsAt(rm, (i*rls)+1)
			if (p > minx) && (p < maxx) {
				spanned = 0
				crossed = 0
				r = ra
				for r < rb {
					cy = (port.CellsAt(rw, (r*rws)+6) + port.CellsAt(rw, (r*rws)+7)) / 2
					if (cy >= port.CellsAt(rm, (i*rls)+2)) && (cy <= port.CellsAt(rm, (i*rls)+3)) {
						spanned += 1
						k = 0
						for k < port.CellsAt(rw, (r*rws)+1) {
							w = port.CellsAt(wl, port.CellsAt(rw, r*rws)+k)
							if (evidence.WdGet(wd, w, evidence.HdX0()) < p) && (evidence.WdGet(wd, w, evidence.HdX1()) > p) {
								crossed = 1
							}
							k += 1
						}
					}
					r += 1
				}
				if (crossed == 0) && ((spanned >= 2) && ((spanned * 5) >= (n * 3))) {
					port.CellsPush(cl, p)
					port.CellsPush(cl, port.CellsAt(rm, (i*rls)+2))
					port.CellsPush(cl, port.CellsAt(rm, (i*rls)+3))
				}
			}
		}
		i += 1
	}
	return port.CellsLen(cl)
}

func tbChannelAdd(ch *port.Cells, p int32) int32 {
	// D559: a channel of no width at x p, in its place among the channels `ch` (pairs of start and end, in order of x), so that a column
	// boundary stands at p: nothing is added when p lies in a channel already (its midpoint is the boundary, with words either side).
	// Answers 1 when one was added.
	var n int32 = port.CellsLen(ch) / 2
	var i int32 = 0
	var at int32 = 0
	var k int32 = 0
	for i < n {
		if (port.CellsAt(ch, i*2) <= p) && (p <= port.CellsAt(ch, (i*2)+1)) {
			return 0
		}
		if port.CellsAt(ch, i*2) < p {
			at += 1
		}
		i += 1
	}
	port.CellsPush(ch, 0)
	port.CellsPush(ch, 0)
	k = port.CellsLen(ch) - 1
	for k >= ((at * 2) + 2) {
		port.CellsSet(ch, k, port.CellsAt(ch, k-2))
		k -= 1
	}
	port.CellsSet(ch, at*2, p)
	port.CellsSet(ch, (at*2)+1, p)
	return 1
}

func tbSubEnd(wd *port.Cells, et *port.Cells, wl *port.Cells, cl *port.Cells, k int32, kend int32, cy int32, style int32) int32 {
	// Physical and inferred cuts separate words, but never a glued currency pair or a leader.
	var e int32 = k + 1
	var j int32 = 0
	var split int32 = 0
	for (e < kend) && (split == 0) {
		j = 0
		for j < port.CellsLen(cl) {
			if !tbGlued(wd, et, port.CellsAt(wl, e-1), port.CellsAt(wl, e), style) && ((evidence.WdGet(wd, port.CellsAt(wl, e-1), evidence.HdX1()) <= port.CellsAt(cl, j)) && ((port.CellsAt(cl, j) <= evidence.WdGet(wd, port.CellsAt(wl, e), evidence.HdX0())) && ((cy >= port.CellsAt(cl, j+1)) && (cy <= port.CellsAt(cl, j+2))))) {
				split = 1
			}
			j += 3
		}
		if split == 0 {
			e += 1
		}
	}
	return e
}

func tbCrossed(wd *port.Cells, w0 int32, w1 int32, x int32, ya int32, yb int32) bool {
	// P12.2: does a word whose centre is in the rows ya..yb lie across x (starts before it, ends after it).
	var w int32 = w0
	for w < w1 {
		if (evidence.WdGet(wd, w, evidence.HdX0()) < x) && (evidence.WdGet(wd, w, evidence.HdX1()) > x) {
			if (evidence.WdGet(wd, w, evidence.HdTlen()) > 0) && tbUpright(wd, w) {
				var cy int32 = (evidence.WdGet(wd, w, evidence.HdY0()) + evidence.WdGet(wd, w, evidence.HdY1())) / 2
				if (cy >= ya) && (cy <= yb) {
					return 1 == 1
				}
			}
		}
		w += 1
	}
	return 0 == 1
}

func tbSingleWidgetBand(an *port.Cells, page int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// D757: a ruled band with text fields on a single baseline is one form row, including a tall wrapped total label. Printed digits in its instructions do not prove extra rows.
	var i int32 = 0
	var first int32 = -1
	var found int32 = 0
	for i < (port.CellsLen(an) / anStride) {
		var o int32 = i * anStride
		var cx int32 = (port.CellsAt(an, o+4) + port.CellsAt(an, o+6)) / 2
		var cy int32 = (port.CellsAt(an, o+5) + port.CellsAt(an, o+7)) / 2
		if (port.CellsAt(an, o+1) == pdfannot.AnField()) && ((port.CellsAt(an, o) + 1) == page) && (port.CellsAt(an, o+8) >= 4) && (cx >= x0) && (cx <= x1) && (cy >= y0) && (cy < y1) {
			if (first >= 0) && (tbAbs(cy-first) > posTol) {
				return 0
			}
			first = cy
			found = 1
		}
		i += 1
	}
	return found
}

func tbSplitRows(rm *port.Cells, root int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, xs *port.Cells, ys *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, occ *port.Cells, rmap *port.Cells, so *port.Cells, bd *port.Cells, an *port.Cells, page int32) int32 {
	// P12.2 (smoke review, issue 2: BLS, BEA, a 10-K): the rows of a lattice with fewer row cuts than its text has rows. A band between two
	// rules that are drawn across every column, with no word crossing an undrawn outer boundary, holds the rows of a table when the baselines of its words, told into table rows as an unruled table's
	// D634: words may cross undrawn interior boundaries: those labels span columns in their own row, rather than blocking every row cut in the band. The baseline rows, told as an unruled table's
	// are (`tb-row-map`, the lattice's column boundaries the columns: a wrapped cell's tight lines are one row), make at least `TB_SPLIT_MIN` rows, three in
	// four of the baselines have words in two columns or more, and three in four have a digit (a header of two-line cells has none, or few: it is the
	// band's own). The cut between two such rows is at the middle of their baselines; the cuts are added to `ys` (kept in order) and listed in `so`
	// (emptied first), and the band's top and bottom are a pair of `bd` (emptied first). Answers how many cuts.
	var nc int32 = port.CellsLen(xs) - 1
	var nr int32 = port.CellsLen(ys) - 1
	var r int32 = 0
	var c int32 = 0
	var closed int32 = 1
	var nb int32 = 0
	var rows int32 = 0
	var i int32 = 0
	var k int32 = 0
	var tab int32 = 0
	var num int32 = 0
	var col int32 = 0
	var prev int32 = -1
	var ncol int32 = 0
	var hasnum int32 = 0
	var w int32 = 0
	port.CellsDrop(so, 0)
	port.CellsDrop(bd, 0)
	for r < nr {
		closed = 1
		c = 0
		for (c < nc) && (closed == 1) {
			if !tbClosed(rm, root, 0, port.CellsAt(ys, r), port.CellsAt(xs, c), port.CellsAt(xs, c+1)) {
				closed = 0
			}
			if !tbClosed(rm, root, 0, port.CellsAt(ys, r+1), port.CellsAt(xs, c), port.CellsAt(xs, c+1)) {
				closed = 0
			}
			c += 1
		}
		c = 0
		for (c <= nc) && (closed == 1) {
			if !tbClosed(rm, root, 1, port.CellsAt(xs, c), port.CellsAt(ys, r), port.CellsAt(ys, r+1)) {
				if (c == 0) || (c == nc) {
					if tbCrossed(wd, w0, w1, port.CellsAt(xs, c), port.CellsAt(ys, r), port.CellsAt(ys, r+1)) {
						closed = 0
					}
				}
			}
			c += 1
		}
		if (closed == 1) && (tbSingleWidgetBand(an, page, port.CellsAt(xs, 0), port.CellsAt(ys, r), port.CellsAt(xs, nc), port.CellsAt(ys, r+1)) == 0) {
			nb = tbRows(wd, et, w0, w1, port.CellsAt(xs, 0), port.CellsAt(ys, r), port.CellsAt(xs, nc), port.CellsAt(ys, r+1), wl, rw, sg)
			if nb >= tbSplitMin {
				port.CellsDrop(ch, 0)
				c = 1
				for c < nc {
					tbChannelAdd(ch, port.CellsAt(xs, c))
					c += 1
				}
				rows = tbRowMap(wd, et, wl, rw, sg, ch, 0, nb, nc, rmap, occ)
				tab = 0
				num = 0
				i = 0
				for i < nb {
					prev = -1
					ncol = 0
					hasnum = 0
					k = 0
					for k < port.CellsAt(rw, (i*rws)+1) {
						w = port.CellsAt(wl, port.CellsAt(rw, i*rws)+k)
						col = tbColOf(ch, tbWordCx(wd, w))
						if col != prev {
							ncol += 1
							prev = col
						}
						if tbWordDigit(wd, et, w) {
							hasnum = 1
						}
						k += 1
					}
					if ncol >= 2 {
						tab += 1
					}
					num += hasnum
					i += 1
				}
				if (rows >= tbSplitMin) && (((tab * 4) >= (nb * 3)) && ((num * 4) >= (nb * 3))) {
					port.CellsPush(bd, port.CellsAt(ys, r))
					port.CellsPush(bd, port.CellsAt(ys, r+1))
					i = 1
					for i < nb {
						if port.CellsAt(rmap, i) != port.CellsAt(rmap, i-1) {
							port.CellsPush(so, ((port.CellsAt(rw, ((i-1)*rws)+6)+port.CellsAt(rw, ((i-1)*rws)+7))+(port.CellsAt(rw, (i*rws)+6)+port.CellsAt(rw, (i*rws)+7)))/4)
						}
						i += 1
					}
				}
			}
		}
		r += 1
	}
	i = 0
	for i < port.CellsLen(so) {
		port.CellsPush(ys, port.CellsAt(so, i))
		i += 1
	}
	tbSortNums(ys)
	return port.CellsLen(so)
}

func tbNumChar(cp int32) bool {
	// A character a number may hold besides digits: separators, signs, currency, percent, brackets.
	return (cp == 44) || ((cp == 46) || ((cp == 45) || ((cp == 43) || ((cp == 37) || ((cp == 36) || ((cp == 8364) || ((cp == 163) || ((cp == 165) || ((cp == 40) || ((cp == 41) || ((cp == 47) || ((cp == 58) || ((cp == 8722) || ((cp == 8211) || ((cp == 160) || ((cp == 8201) || (cp == 8239)))))))))))))))))
}

func tbForcedCuts(wd *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ra int32, rb int32, nch int32, minx int32, kc *port.Cells) int32 {
	// Header-anchored bands missing from the body channels. kc records are cut-before, header-left, header-right.
	port.CellsDrop(kc, 0)
	var r int32 = ra * rws
	var n int32 = port.CellsAt(rw, r+9)
	var first int32 = port.CellsAt(rw, r+8)
	var i int32 = 0
	var cut int32 = minx
	if (n <= (nch + 1)) || ((n < 3) || (n > 40)) {
		return 0
	}
	for i < port.CellsAt(rw, r+1) {
		var w int32 = port.CellsAt(wl, port.CellsAt(rw, r)+i)
		if (evidence.WdGet(wd, w, evidence.WfStyle()) & model.SyBold()) == 0 {
			return 0
		}
		i += 1
	}
	i = 0
	for i < n {
		var s int32 = (first + i) * sgs
		var left int32 = port.CellsAt(sg, s+1)
		var right int32 = port.CellsAt(sg, s+2)
		if i > 0 {
			cut = (left + port.CellsAt(sg, ((first+(i-1))*sgs)+2)) / 2
		}
		port.CellsPush(kc, cut)
		port.CellsPush(kc, left)
		port.CellsPush(kc, right)
		i += 1
	}
	return n
}

func tbNumericCol(wd *port.Cells, et *port.Cells, wl *port.Cells, ks int32, ke int32, kc *port.Cells, ch *port.Cells, fallback int32) int32 {
	var k int32 = ks
	var j int32 = 0
	var digits int32 = 0
	var edge int32 = -2000000000
	var best int32 = -1
	var dist int32 = (2 * tbHeadTol) + 1
	if (port.CellsLen(kc) == 0) || ((port.CellsLen(kc) / 3) != ((port.CellsLen(ch) / 2) + 1)) {
		return fallback
	}
	for k < ke {
		var w int32 = port.CellsAt(wl, k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		edge = tbMax(edge, evidence.WdGet(wd, w, evidence.HdX1()))
		j = 0
		for j < tl {
			var cp int32 = port.CellsAt(et, ts+j)
			if (cp >= 48) && (cp <= 57) {
				digits += 1
			} else if !tbNumChar(cp) {
				return fallback
			}
			j += 1
		}
		k += 1
	}
	if digits == 0 {
		return fallback
	}
	k = 0
	for k < (port.CellsLen(kc) / 3) {
		var d int32 = tbAbs(edge - port.CellsAt(kc, (k*3)+2))
		if d < dist {
			dist = d
			best = k
		}
		k += 1
	}
	if best >= 0 {
		return best
	}
	return fallback
}

func tbNumberWord(wd *port.Cells, et *port.Cells, w int32) int32 {
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var i int32 = 0
	var digits int32 = 0
	var formatted int32 = 0
	for i < tl {
		var cp int32 = port.CellsAt(et, ts+i)
		if (cp >= 48) && (cp <= 57) {
			digits += 1
		} else if !tbNumChar(cp) {
			return 0
		}
		if (cp == 46) || ((cp == 44) || (cp == 37)) {
			formatted = 1
		}
		i += 1
	}
	if (digits > 0) && (formatted == 1) {
		return 1
	}
	return 0
}

func tbNumberCutAdd(ch *port.Cells, p int32, lo int32, hi int32) int32 {
	var i int32 = 0
	var best int32 = -1
	var dist int32 = tbHeadTol + 1
	for i < port.CellsLen(ch) {
		var mid int32 = (port.CellsAt(ch, i) + port.CellsAt(ch, i+1)) / 2
		if (mid >= lo) && (mid <= hi) {
			return 0
		}
		if (p >= port.CellsAt(ch, i)) && (p <= port.CellsAt(ch, i+1)) {
			port.CellsSet(ch, i, p)
			port.CellsSet(ch, i+1, p)
			return 0
		}
		if port.CellsAt(ch, i) == port.CellsAt(ch, i+1) {
			if tbAbs(p-port.CellsAt(ch, i)) < dist {
				best = i
				dist = tbAbs(p - port.CellsAt(ch, i))
			}
		}
		i += 2
	}
	if best >= 0 {
		port.CellsSet(ch, best, p)
		port.CellsSet(ch, best+1, p)
		return 0
	}
	return tbChannelAdd(ch, p)
}

func tbNumberCuts(wd *port.Cells, et *port.Cells, wl *port.Cells, rw *port.Cells, ra int32, rb int32, profile int32, ch *port.Cells, anchors *port.Cells, order *port.Cells, cuts *port.Cells) int32 {
	var r int32 = ra
	var k int32 = 0
	var i int32 = 0
	var j int32 = 0
	var support int32 = 3
	var chain int32 = 0
	var hits int32 = 0
	var left int32 = 0
	var right int32 = 0
	var lo int32 = 0
	var hi int32 = 0
	port.CellsDrop(anchors, 0)
	port.CellsDrop(order, 0)
	port.CellsDrop(cuts, 0)
	if profile == pfWhitespace {
		return 0
	}
	k = port.CellsAt(rw, ra*rws)
	for k < (port.CellsAt(rw, (rb-1)*rws) + port.CellsAt(rw, ((rb-1)*rws)+1)) {
		port.CellsPush(anchors, port.CellsAt(wl, k))
		k += 1
	}
	tbSortNums(anchors)
	i = 0
	for i < port.CellsLen(anchors) {
		var w int32 = port.CellsAt(anchors, i)
		var line int32 = evidence.WdGet(wd, w, evidence.HdLine())
		var page int32 = evidence.WdGet(wd, w, evidence.HdPage())
		var prev int32 = w - 1
		var next int32 = w + 1
		if line >= 0 {
			for (prev >= 0) && ((evidence.WdGet(wd, prev, evidence.HdLine()) == line) && (evidence.WdGet(wd, prev, evidence.HdPage()) == page)) && ((evidence.WdGet(wd, prev, evidence.HdTlen()) == 0) || !tbUpright(wd, prev)) {
				prev -= 1
			}
			for (next < evidence.WdCount(wd)) && ((evidence.WdGet(wd, next, evidence.HdLine()) == line) && (evidence.WdGet(wd, next, evidence.HdPage()) == page)) && ((evidence.WdGet(wd, next, evidence.HdTlen()) == 0) || !tbUpright(wd, next)) {
				next += 1
			}
			if (prev >= 0) && ((evidence.WdGet(wd, prev, evidence.HdLine()) == line) && (evidence.WdGet(wd, prev, evidence.HdPage()) == page)) && ((i == 0) || (port.CellsAt(anchors, i-1) != prev)) {
				return 0
			}
			if (next < evidence.WdCount(wd)) && ((evidence.WdGet(wd, next, evidence.HdLine()) == line) && (evidence.WdGet(wd, next, evidence.HdPage()) == page)) && (((i + 1) == port.CellsLen(anchors)) || (port.CellsAt(anchors, i+1) != next)) {
				return 0
			}
		}
		i += 1
	}
	port.CellsDrop(anchors, 0)
	i = 0
	for r < rb {
		var start int32 = port.CellsAt(rw, r*rws)
		var n int32 = port.CellsAt(rw, (r*rws)+1)
		var size int32 = port.CellsAt(rw, (r*rws)+3)
		k = 0
		for (k + 1) < n {
			var a int32 = port.CellsAt(wl, start+k)
			var b int32 = port.CellsAt(wl, (start+k)+1)
			var gap int32 = evidence.WdGet(wd, b, evidence.HdX0()) - evidence.WdGet(wd, a, evidence.HdX1())
			if (gap > 0) && ((gap <= (size * 8)) && ((tbNumberWord(wd, et, a) == 1) && (tbNumberWord(wd, et, b) == 1))) {
				chain = 0
				if k > 0 {
					var prev int32 = port.CellsAt(wl, start+(k-1))
					if (tbNumberWord(wd, et, prev) == 1) && ((evidence.WdGet(wd, a, evidence.HdX0()) > evidence.WdGet(wd, prev, evidence.HdX1())) && ((evidence.WdGet(wd, a, evidence.HdX0()) - evidence.WdGet(wd, prev, evidence.HdX1())) <= (size * 8))) {
						chain = 1
					}
				}
				if (k + 2) < n {
					var next int32 = port.CellsAt(wl, start+(k+2))
					if (tbNumberWord(wd, et, next) == 1) && ((evidence.WdGet(wd, next, evidence.HdX0()) > evidence.WdGet(wd, b, evidence.HdX1())) && ((evidence.WdGet(wd, next, evidence.HdX0()) - evidence.WdGet(wd, b, evidence.HdX1())) <= (size * 8))) {
						chain = 1
					}
				}
				if port.CellsLen(anchors) >= 16000 {
					return 0
				}
				port.CellsPush(order, port.CellsLen(anchors)/4)
				port.CellsPush(anchors, evidence.WdGet(wd, a, evidence.HdX1()))
				port.CellsPush(anchors, evidence.WdGet(wd, b, evidence.HdX1()))
				port.CellsPush(anchors, evidence.WdGet(wd, b, evidence.HdX0()))
				port.CellsPush(anchors, chain)
			}
			k += 1
		}
		r += 1
	}
	if (rb - ra) <= 4 {
		support = 2
	}
	tbSortIdx(order, anchors, 4, 0, 1)
	for i < port.CellsLen(order) {
		var a int32 = port.CellsAt(order, i) * 4
		left = port.CellsAt(anchors, a)
		right = port.CellsAt(anchors, a+1)
		lo = left
		hi = port.CellsAt(anchors, a+2)
		chain = port.CellsAt(anchors, a+3)
		hits = 1
		j = i + 1
		for (j < port.CellsLen(order)) && ((tbAbs(port.CellsAt(anchors, port.CellsAt(order, j)*4)-left) <= 200) && (tbAbs(port.CellsAt(anchors, (port.CellsAt(order, j)*4)+1)-right) <= 200)) {
			var b int32 = port.CellsAt(order, j) * 4
			lo = tbMax(lo, port.CellsAt(anchors, b))
			hi = tbMin(hi, port.CellsAt(anchors, b+2))
			chain = tbMax(chain, port.CellsAt(anchors, b+3))
			hits += 1
			j += 1
		}
		if (hi > lo) && ((hits >= support) || ((chain == 1) && ((profile == pfPartial) || (profile == pfShaded)))) {
			var p int32 = (lo + hi) / 2
			tbNumberCutAdd(ch, p, lo, hi)
			port.CellsPush(cuts, p)
			port.CellsPush(cuts, lo)
			port.CellsPush(cuts, hi)
		}
		i = j
	}
	return port.CellsLen(cuts) / 3
}

func tbBoxBreak(rm *port.Cells, x0 int32, x1 int32, top int32, last int32, next int32) int32 {
	var i int32 = 0
	var left int32 = 0
	var right int32 = 0
	var newleft int32 = 0
	var newright int32 = 0
	if (next - last) <= (posTol * 2) {
		return 0
	}
	for i < tbRowsOf(rm, rls) {
		if port.CellsAt(rm, i*rls) == 1 {
			var x int32 = port.CellsAt(rm, (i*rls)+1)
			var a int32 = port.CellsAt(rm, (i*rls)+2)
			var b int32 = port.CellsAt(rm, (i*rls)+3)
			if (a <= (top + posTol)) && (tbAbs(b-last) <= posTol) {
				if tbAbs(x-x0) <= (posTol * 2) {
					left = 1
				}
				if tbAbs(x-x1) <= (posTol * 2) {
					right = 1
				}
			}
			if (tbAbs(a-next) <= posTol) && (b > (next + 1000)) {
				if tbAbs(x-x0) <= (posTol * 2) {
					newleft = 1
				}
				if tbAbs(x-x1) <= (posTol * 2) {
					newright = 1
				}
			}
		}
		i += 1
	}
	if (left == 1) && ((right == 1) && ((newleft == 1) && (newright == 1))) {
		return 1
	}
	return 0
}

func tbBoxCrossing(rm *port.Cells, x0 int32, x1 int32, y0 int32, y1 int32) int32 {
	var i int32 = 0
	var n int32 = tbRowsOf(rm, rls)
	for (i + 1) < n {
		if (port.CellsAt(rm, i*rls) == 0) && (port.CellsAt(rm, (i+1)*rls) == 0) {
			var a int32 = i * rls
			var b int32 = (i + 1) * rls
			var last int32 = port.CellsAt(rm, a+1)
			var next int32 = port.CellsAt(rm, b+1)
			var left int32 = port.CellsAt(rm, a+2)
			var right int32 = port.CellsAt(rm, a+3)
			if ((last > y0) && (next < y1)) && ((left <= (x0 + posTol)) && (right >= (x1 - posTol))) {
				if tbBoxBreak(rm, left, right, y0, last, next) == 1 {
					return 1
				}
			}
		}
		i += 1
	}
	return 0
}

func tbTextGrid(wd *port.Cells, et *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, rm *port.Cells, kc *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells, page int32, ra int32, rb int32, profile int32, score int32, ext int32, bx0 int32, by0 int32, bx1 int32, by1 int32) int32 {
	// The cells of the rows ra..rb (see the head of this section) as a candidate table of this profile:
	// ext 1 means `rmap` already says which table row each baseline row is (shaded: the fills' bands); ext 2 is a selected model fit. The box
	// bx0..by1 widens the box of the words (the rules, the fills): 2000000000 2000000000 -2000000000 -2000000000
	// for none. `rm` are the page's merged rules (empty for none): a vertical one that runs along most of the rows between two words is
	// a column cut, whatever the profile (D559). Answers the
	// table's index, -1 when there are not two columns and two rows.
	var ntab int32 = 0
	var sumsz int64 = int64(0)
	var r int32 = ra
	var nch int32 = 0
	var inferred int32 = 0
	var ncols int32 = 0
	var nrows int32 = 0
	var c int32 = 0
	var s int32 = 0
	var q int32 = 0
	var a int32 = 0
	var b int32 = 0
	var tr int32 = 0
	var ks int32 = 0
	var ke int32 = 0
	var kx int32 = 0
	var sty int32 = 0
	var minx int32 = 2000000000
	var maxx int32 = -2000000000
	var miny int32 = 2000000000
	var maxy int32 = -2000000000
	for r < rb {
		if port.CellsAt(rw, (r*rws)+9) >= 2 {
			ntab += 1
		}
		sumsz = sumsz + int64(port.CellsAt(rw, (r*rws)+3))
		if port.CellsAt(rw, (r*rws)+4) < minx {
			minx = port.CellsAt(rw, (r*rws)+4)
		}
		if port.CellsAt(rw, (r*rws)+5) > maxx {
			maxx = port.CellsAt(rw, (r*rws)+5)
		}
		if port.CellsAt(rw, (r*rws)+6) < miny {
			miny = port.CellsAt(rw, (r*rws)+6)
		}
		if port.CellsAt(rw, (r*rws)+7) > maxy {
			maxy = port.CellsAt(rw, (r*rws)+7)
		}
		r += 1
	}
	if (ntab < 2) || ((rb - ra) <= 1) {
		return -1
	}
	if tbBoxCrossing(rm, minx, maxx, miny, maxy) == 1 {
		return -1
	}
	nch = tbChannels(wd, et, wl, rw, sg, ra, rb, ntab/6, int32(((sumsz/int64(rb-ra))*int64(segNum))/int64(segDen)), ch, st, en)
	if tbCutList(wd, wl, rw, rm, ra, rb, minx, maxx, st) > 0 {
		c = 0
		for c < port.CellsLen(st) {
			tbChannelAdd(ch, port.CellsAt(st, c))
			c += 3
		}
	}
	nch = port.CellsLen(ch) / 2
	inferred = tbNumberCuts(wd, et, wl, rw, ra, rb, profile, ch, en, so, pr)
	if inferred == 0 {
		nch = tbChannels(wd, et, wl, rw, sg, ra, rb, ntab/6, int32(((sumsz/int64(rb-ra))*int64(segNum))/int64(segDen)), ch, st, en)
	} else {
		nch = port.CellsLen(ch) / 2
	}
	if tbForcedCuts(wd, wl, rw, sg, ra, rb, nch, minx, kc) > 0 {
		port.CellsDrop(ch, 0)
		c = 1
		for c < (port.CellsLen(kc) / 3) {
			port.CellsPush(ch, port.CellsAt(kc, c*3))
			port.CellsPush(ch, port.CellsAt(kc, c*3))
			c += 1
		}
		nch = port.CellsLen(ch) / 2
	}
	// D559: a vertical rule along most of the rows between two words is a boundary of its own (a channel of no width) where the whitespace has none.
	if tbCutList(wd, wl, rw, rm, ra, rb, minx, maxx, st) > 0 {
		c = 0
		for c < port.CellsLen(st) {
			tbChannelAdd(ch, port.CellsAt(st, c))
			c += 3
		}
		nch = port.CellsLen(ch) / 2
	}
	c = 0
	for c < port.CellsLen(pr) {
		tbNumberCutAdd(ch, port.CellsAt(pr, c), port.CellsAt(pr, c+1), port.CellsAt(pr, c+2))
		c += 3
	}
	nch = port.CellsLen(ch) / 2
	if nch < 1 {
		return -1
	}
	ncols = nch + 1
	if ncols > 40 {
		return -1
	}
	if ext == 0 {
		nrows = tbRowMap(wd, et, wl, rw, sg, ch, ra, rb, ncols, rmap, st)
	} else {
		nrows = 0
		r = 0
		for r < (rb - ra) {
			if port.CellsAt(rmap, r) >= nrows {
				nrows = port.CellsAt(rmap, r) + 1
			}
			r += 1
		}
	}
	if nrows < 2 {
		return -1
	}
	// The column cuts again, in `st` (scratch no longer): the words either side of one are cells of their own whatever the chunk.
	tbCutList(wd, wl, rw, rm, ra, rb, minx, maxx, st)
	if port.CellsLen(pr) > 0 {
		r = ra
		for r < rb {
			var numeric int32 = 0
			var wi int32 = 0
			for wi < port.CellsAt(rw, (r*rws)+1) {
				if tbNumberWord(wd, et, port.CellsAt(wl, port.CellsAt(rw, r*rws)+wi)) == 1 {
					numeric += 1
				}
				wi += 1
			}
			if ((port.CellsAt(rw, (r*rws)+9) * 2) >= ncols) || (numeric >= 2) {
				c = 0
				for c < port.CellsLen(pr) {
					port.CellsPush(st, port.CellsAt(pr, c))
					port.CellsPush(st, port.CellsAt(rw, (r*rws)+6))
					port.CellsPush(st, port.CellsAt(rw, (r*rws)+7))
					c += 3
				}
			}
			r += 1
		}
	}
	port.CellsDrop(gm, 0)
	port.CellsDrop(gs, 0)
	port.CellsDrop(en, 0)
	port.CellsDrop(ry, 0)
	c = 0
	for c < (nrows * ncols) {
		port.CellsPush(gm, -1)
		port.CellsPush(gs, 0)
		port.CellsPush(en, -1)
		c += 1
	}
	c = 0
	for c < nrows {
		port.CellsPush(ry, 2000000000)
		port.CellsPush(ry, -2000000000)
		c += 1
	}
	r = ra
	for r < rb {
		tr = port.CellsAt(rmap, r-ra)
		sty = tbCurrencyStyle(wd, et, wl, port.CellsAt(rw, r*rws), port.CellsAt(rw, (r*rws)+1))
		if tr >= 0 {
			if port.CellsAt(rw, (r*rws)+6) < port.CellsAt(ry, tr*2) {
				port.CellsSet(ry, tr*2, port.CellsAt(rw, (r*rws)+6))
			}
			if port.CellsAt(rw, (r*rws)+7) > port.CellsAt(ry, (tr*2)+1) {
				port.CellsSet(ry, (tr*2)+1, port.CellsAt(rw, (r*rws)+7))
			}
			s = 0
			for s < port.CellsAt(rw, (r*rws)+9) {
				q = port.CellsAt(rw, (r*rws)+8) + s
				ks = port.CellsAt(sg, (q*sgs)+3)
				ke = ks + port.CellsAt(sg, (q*sgs)+4)
				for ks < ke {
					kx = tbSubEnd(wd, et, wl, st, ks, ke, (port.CellsAt(rw, (r*rws)+6)+port.CellsAt(rw, (r*rws)+7))/2, sty)
					a = tbColOf(ch, tbFirstCx(wd, et, wl, ks, kx))
					a = tbNumericCol(wd, et, wl, ks, kx, kc, ch, a)
					b = tbColOf(ch, tbWordCx(wd, port.CellsAt(wl, kx-1)))
					b = tbNumericCol(wd, et, wl, ks, kx, kc, ch, b)
					if (ext == 2) && (tbPartNumber(wd, et, wl, ks, kx-ks) == 0) {
						for (b > a) && (evidence.WdGet(wd, port.CellsAt(wl, kx-1), evidence.HdX1()) < port.CellsAt(ch, ((b-1)*2)+1)) {
							b -= 1
						}
					}
					if (ext == 2) && ((s + 1) < port.CellsAt(rw, (r*rws)+9)) {
						var ns int32 = q + 1
						var nextcol int32 = tbChunkA(wd, et, wl, sg, ch, ns)
						if nextcol > a {
							b = tbMin(b, nextcol-1)
						}
					}
					if port.CellsAt(gm, (tr*ncols)+a) == -1 {
						var free int32 = 1
						var kf int32 = a
						for kf <= b {
							if port.CellsAt(gm, (tr*ncols)+kf) != -1 {
								free = 0
							}
							kf += 1
						}
						if free == 0 {
							b = a
						}
						kf = a
						for kf <= b {
							port.CellsSet(gm, (tr*ncols)+kf, a)
							kf += 1
						}
						port.CellsSet(gs, (tr*ncols)+a, (b-a)+1)
					}
					ks = kx
				}
				s += 1
			}
		}
		r += 1
	}
	var cfirst int32 = tbRowsOf(tc, tcs)
	tr = 0
	for tr < nrows {
		c = 0
		for c < ncols {
			var st0 int32 = port.CellsAt(gm, (tr*ncols)+c)
			var span int32 = 1
			if st0 >= 0 {
				span = port.CellsAt(gs, (tr*ncols)+st0)
			}
			if (st0 < 0) || (st0 == c) {
				var idx int32 = tbCellAdd(tc, tr, c, 1, span, tbCut(ch, c, minx, maxx), port.CellsAt(ry, tr*2), tbCut(ch, c+span, minx, maxx), port.CellsAt(ry, (tr*2)+1))
				var ki int32 = c
				for ki < (c + span) {
					port.CellsSet(en, (tr*ncols)+ki, idx)
					ki += 1
				}
			}
			c += span
		}
		tr += 1
	}
	port.CellsDrop(pr, 0)
	r = ra
	for r < rb {
		tr = port.CellsAt(rmap, r-ra)
		sty = tbCurrencyStyle(wd, et, wl, port.CellsAt(rw, r*rws), port.CellsAt(rw, (r*rws)+1))
		if tr >= 0 {
			s = 0
			for s < port.CellsAt(rw, (r*rws)+9) {
				q = port.CellsAt(rw, (r*rws)+8) + s
				ks = port.CellsAt(sg, (q*sgs)+3)
				ke = ks + port.CellsAt(sg, (q*sgs)+4)
				for ks < ke {
					kx = tbSubEnd(wd, et, wl, st, ks, ke, (port.CellsAt(rw, (r*rws)+6)+port.CellsAt(rw, (r*rws)+7))/2, sty)
					a = tbColOf(ch, tbFirstCx(wd, et, wl, ks, kx))
					a = tbNumericCol(wd, et, wl, ks, kx, kc, ch, a)
					var cell int32 = port.CellsAt(en, (tr*ncols)+a)
					var kw int32 = ks
					for kw < kx {
						tbPairAdd(pr, wd, cell, port.CellsAt(wl, kw))
						kw += 1
					}
					ks = kx
				}
				s += 1
			}
		}
		r += 1
	}
	tbFlushPairs(pr, so, wd, tc, tw)
	var x0 int32 = minx
	var y0 int32 = miny
	var x1 int32 = maxx
	var y1 int32 = maxy
	if bx0 < x0 {
		x0 = bx0
	}
	if by0 < y0 {
		y0 = by0
	}
	if bx1 > x1 {
		x1 = bx1
	}
	if by1 > y1 {
		y1 = by1
	}
	var t int32 = TbAdd(tb, page, x0, y0, x1, y1, profile, score, nrows, ncols, cfirst, tbRowsOf(tc, tcs)-cfirst)
	var k int32 = 0
	if port.CellsLen(kc) > 0 {
		port.CellsSet(tb, (t*tagtable.Tbs)+31, 1)
	}
	port.CellsSet(tb, (t*tagtable.Tbs)+16, port.CellsLen(tx))
	port.CellsSet(tb, (t*tagtable.Tbs)+17, ncols+1)
	for k <= ncols {
		port.CellsPush(tx, tbCut(ch, k, minx, maxx))
		k += 1
	}
	return t
}

func tbCellNumeric(wd *port.Cells, et *port.Cells, tw *port.Cells, tc *port.Cells, c int32) int32 {
	// 1 when the cell is up to three words made only of digits and number marks, with a digit; else 0.
	var cb int32 = c * tcs
	var n int32 = port.CellsAt(tc, cb+9)
	var from int32 = port.CellsAt(tc, cb+8)
	var digits int32 = 0
	var k int32 = 0
	var j int32 = 0
	if (n == 0) || (n > 3) {
		return 0
	}
	for k < n {
		var w int32 = port.CellsAt(tw, from+k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		j = 0
		for j < tl {
			var cp int32 = port.CellsAt(et, ts+j)
			if (cp >= 48) && (cp <= 57) {
				digits += 1
			} else if !tbNumChar(cp) {
				return 0
			}
			j += 1
		}
		k += 1
	}
	if digits > 0 {
		return 1
	}
	return 0
}

func tbCellSig(wd *port.Cells, et *port.Cells, tw *port.Cells, tc *port.Cells, c int32) int32 {
	// The shape of a number cell (`tb-cell-numeric`), 0 for anything else: 1 + a currency sign, 2 + a decimal point (a dot before a digit).
	// A count or a year has none (0 is 'plain'); an amount of money has both.
	var cb int32 = c * tcs
	var n int32 = port.CellsAt(tc, cb+9)
	var from int32 = port.CellsAt(tc, cb+8)
	var sig int32 = 0
	var k int32 = 0
	var j int32 = 0
	if tbCellNumeric(wd, et, tw, tc, c) == 0 {
		return 0
	}
	for k < n {
		var w int32 = port.CellsAt(tw, from+k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		j = 0
		for j < tl {
			var cp int32 = port.CellsAt(et, ts+j)
			if (cp == 36) || ((cp == 8364) || ((cp == 163) || (cp == 165))) {
				sig |= 1
			}
			if (cp == 46) && ((j + 1) < tl) {
				if (port.CellsAt(et, (ts+j)+1) >= 48) && (port.CellsAt(et, (ts+j)+1) <= 57) {
					sig |= 2
				}
			}
			j += 1
		}
		k += 1
	}
	return sig
}

func tbRowAmounts(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells) int32 {
	// Is row r a row of amounts (D557): one of its cells is a formatted number (a currency sign or a decimal point, `tb-cell-sig`) and the
	// cell below it in the same column is one of the same shape. A bold 'Opening Balance' row over a column of balances is one, a row
	// of years over a column of counts is not; the first is a row of the table and the second its header.
	var c int32 = cfirst
	var d int32 = 0
	var sig int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			sig = tbCellSig(wd, et, tw, tc, c)
			if sig != 0 {
				d = cfirst
				for d < cend {
					if (port.CellsAt(tc, d*tcs) == (r + 1)) && (port.CellsAt(tc, (d*tcs)+1) == port.CellsAt(tc, (c*tcs)+1)) {
						if tbCellSig(wd, et, tw, tc, d) == sig {
							return 1
						}
					}
					d += 1
				}
			}
		}
		c += 1
	}
	return 0
}

func tbCellBold(wd *port.Cells, tw *port.Cells, tc *port.Cells, c int32) int32 {
	// 1 when every word of the cell is bold, 0 when one is not, -1 for an empty cell.
	var cb int32 = c * tcs
	var n int32 = port.CellsAt(tc, cb+9)
	var from int32 = port.CellsAt(tc, cb+8)
	var k int32 = 0
	if n == 0 {
		return -1
	}
	for k < n {
		if (evidence.WdGet(wd, port.CellsAt(tw, from+k), evidence.WfStyle()) & model.SyBold()) == 0 {
			return 0
		}
		k += 1
	}
	return 1
}

func tbRowStat(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells, what int32) int32 {
	// Of the cells that start in row r: what 0 how many are not empty, 1 how many are bold, 2 how many are
	// numeric, 3 how many there are.
	var c int32 = cfirst
	var n int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			if what == 3 {
				n += 1
			}
			if (what == 0) && (port.CellsAt(tc, (c*tcs)+9) > 0) {
				n += 1
			}
			if (what == 1) && (tbCellBold(wd, tw, tc, c) == 1) {
				n += 1
			}
			if (what == 2) && (tbCellNumeric(wd, et, tw, tc, c) == 1) {
				n += 1
			}
		}
		c += 1
	}
	return n
}

func tbRowBold(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells) bool {
	// Is row r bold: it has cells and every one that is not empty is bold.
	var ne int32 = tbRowStat(tc, cfirst, cend, r, wd, et, tw, 0)
	return (ne > 0) && (tbRowStat(tc, cfirst, cend, r, wd, et, tw, 1) == ne)
}

func tbNumCols(tb *port.Cells, k int32, r0 int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// How many columns, over the rows from r0 on, have at least 3 cells of which 4/5 are numeric.
	var b int32 = k * tagtable.Tbs
	var ncols int32 = port.CellsAt(tb, b+8)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var col int32 = 0
	var c int32 = 0
	var ne int32 = 0
	var nn int32 = 0
	var total int32 = 0
	for col < ncols {
		ne = 0
		nn = 0
		c = cfirst
		for c < cend {
			if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && (port.CellsAt(tc, (c*tcs)+3) == 1)) {
				if port.CellsAt(tc, (c*tcs)+9) > 0 {
					ne += 1
					if tbCellNumeric(wd, et, tw, tc, c) == 1 {
						nn += 1
					}
				}
			}
			c += 1
		}
		if (ne >= 3) && ((nn * 10) >= (ne * 8)) {
			total += 1
		}
		col += 1
	}
	return total
}

func tbLabelRow(tb *port.Cells, k int32, r int32, tc *port.Cells) bool {
	// P12.2: is row r of table k a section's label and no header: one cell with text, in the leftmost column that has any, that spans none (a
	// header that is one cell, `December 31,` over the year columns, is over them).
	var b int32 = k * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var cnt int32 = 0
	var only int32 = -1
	var mincol int32 = 2000000000
	for c < cend {
		if port.CellsAt(tc, (c*tcs)+9) > 0 {
			if port.CellsAt(tc, (c*tcs)+1) < mincol {
				mincol = port.CellsAt(tc, (c*tcs)+1)
			}
			if port.CellsAt(tc, c*tcs) == r {
				cnt += 1
				only = c
			}
		}
		c += 1
	}
	if cnt != 1 {
		return 0 == 1
	}
	return (port.CellsAt(tc, (only*tcs)+3) == 1) && (port.CellsAt(tc, (only*tcs)+1) == mincol)
}

func tbCellGrouped(wd *port.Cells, et *port.Cells, tw *port.Cells, tc *port.Cells, c int32) bool {
	// P12.2: is the cell a number whose thousands are grouped (`35,595`: a comma between a digit and three digits): a count is not a year.
	if tbCellNumeric(wd, et, tw, tc, c) == 0 {
		return 0 == 1
	}
	var cb int32 = c * tcs
	var from int32 = port.CellsAt(tc, cb+8)
	var k int32 = 0
	var j int32 = 0
	for k < port.CellsAt(tc, cb+9) {
		var w int32 = port.CellsAt(tw, from+k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		j = 1
		for (j + 3) < tl {
			if (port.CellsAt(et, ts+j) == 44) && ((port.CellsAt(et, (ts+j)+-1) >= 48) && (port.CellsAt(et, (ts+j)+-1) <= 57)) {
				if ((port.CellsAt(et, (ts+j)+1) >= 48) && (port.CellsAt(et, (ts+j)+1) <= 57)) && (((port.CellsAt(et, (ts+j)+2) >= 48) && (port.CellsAt(et, (ts+j)+2) <= 57)) && ((port.CellsAt(et, (ts+j)+3) >= 48) && (port.CellsAt(et, (ts+j)+3) <= 57))) {
					return 1 == 1
				}
			}
			j += 1
		}
		k += 1
	}
	return 0 == 1
}

func tbRowFormatted(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells) int32 {
	// P12.2: does row r have two cells or more that are formatted numbers (`tb-cell-sig`: a currency sign or a decimal point; or grouped thousands)?
	var c int32 = cfirst
	var n int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			if (tbCellSig(wd, et, tw, tc, c) != 0) || tbCellGrouped(wd, et, tw, tc, c) {
				n += 1
			}
		}
		c += 1
	}
	if n >= 2 {
		return 1
	}
	return 0
}

func tbHeadRows(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// How many leading rows are the header: the rows above the top rule that line up with the body's columns (D557: field 22,
	// written when the candidate was built), a header the producer set in another type is a header whatever the first body row is;
	// else the bold ones (a table of bold rows has none, and a header is
	// at most half of the rows); else, when the first row has no number and a column below it is numeric,
	// that one row.
	var b int32 = k * tagtable.Tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var h int32 = 0
	if (port.CellsAt(tb, b+22) > 0) && ((port.CellsAt(tb, b+22) < (nrows - 1)) || (((port.CellsAt(tb, b+31) & tbLedgerSplit) != 0) && (port.CellsAt(tb, b+22) < nrows))) {
		return port.CellsAt(tb, b+22)
	}
	for (h < (nrows - 1)) && (tbRowBold(tc, cfirst, cend, h, wd, et, tw) && ((tbRowAmounts(tc, cfirst, cend, h, wd, et, tw) == 0) && !((h > 0) && tbLabelRow(tb, k, h, tc)))) {
		h += 1
	}
	// P12.2 (smoke review, issue 3: the BLS, BEA and US courts' tables): a header of cells that wrap, set in the type of the body or its first row alone in
	// bold, is every row above the first row of amounts (`tb-row-formatted`: two formatted numbers, with a decimal point, a currency sign or grouped
	// thousands) when there are two or more of them, more than the bold ones, and they are not more than a third of the table.
	var f int32 = 0
	for (f < (nrows - 1)) && (tbRowFormatted(tc, cfirst, cend, f, wd, et, tw) == 0) {
		f += 1
	}
	for (f > 0) && tbLabelRow(tb, k, f-1, tc) {
		f -= 1
	}
	if (f >= 2) && ((f > h) && ((f < (nrows - 1)) && ((f * 3) <= nrows))) {
		return f
	}
	if (h > 0) && ((h * 2) <= (nrows + 1)) {
		return h
	}
	if (nrows >= 3) && (tbRowStat(tc, cfirst, cend, 0, wd, et, tw, 2) == 0) {
		if (tbRowStat(tc, cfirst, cend, 0, wd, et, tw, 0) >= 2) && (tbNumCols(tb, k, 1, wd, et, tc, tw) >= 1) {
			return 1
		}
	}
	return 0
}

func tbFootRows(tb *port.Cells, k int32, nhead int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// 1 when the last row is bold and the row above it is not, with at least two body rows; else 0.
	var b int32 = k * tagtable.Tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	if (nrows - nhead) < 3 {
		return 0
	}
	if tbRowBold(tc, cfirst, cend, nrows-1, wd, et, tw) && !tbRowBold(tc, cfirst, cend, nrows-2, wd, et, tw) {
		// P12.2 (smoke review, issue 21): a cell whose row span goes down into the last row keeps the row in the body: a row group does not cross
		// from `tbody` into `tfoot` (invalid HTML), and the span is not split: the total is the last row of its group.
		var c int32 = cfirst
		for c < cend {
			if (port.CellsAt(tc, c*tcs) < (nrows - 1)) && ((port.CellsAt(tc, c*tcs) + port.CellsAt(tc, (c*tcs)+2)) > (nrows - 1)) {
				return 0
			}
			c += 1
		}
		return 1
	}
	return 0
}

func tbColAlign(tb *port.Cells, k int32, col int32, r0 int32, r1 int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The alignment (an `al` code, 0 none) of the cells of column `col` in rows r0..r1 (single-column ones),
	// decided together against their text extent (SPEC 10.10): start when every start gap is within t (a
	// quarter of the size) and the end gaps vary by more than 2t, end the other way round, center when the
	// two gaps agree within t on every cell and the start gap varies.
	var b int32 = k * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var n int32 = 0
	var box0 int32 = 2000000000
	var box1 int32 = -2000000000
	var size int32 = 0
	var smax int32 = -2000000000
	var smin int32 = 2000000000
	var emax int32 = -2000000000
	var emin int32 = 2000000000
	var cen int32 = 1
	var res int32 = 0
	for c < cend {
		if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && ((port.CellsAt(tc, c*tcs) < r1) && ((port.CellsAt(tc, (c*tcs)+3) == 1) && (port.CellsAt(tc, (c*tcs)+9) > 0)))) {
			n += 1
			if port.CellsAt(tc, (c*tcs)+13) < box0 {
				box0 = port.CellsAt(tc, (c*tcs)+13)
			}
			if port.CellsAt(tc, (c*tcs)+14) > box1 {
				box1 = port.CellsAt(tc, (c*tcs)+14)
			}
			if size == 0 {
				size = evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)), evidence.WfSize())
			}
		}
		c += 1
	}
	if n < 2 {
		return 0
	}
	var t int32 = size / 4
	c = cfirst
	for c < cend {
		if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && ((port.CellsAt(tc, c*tcs) < r1) && ((port.CellsAt(tc, (c*tcs)+3) == 1) && (port.CellsAt(tc, (c*tcs)+9) > 0)))) {
			var sg0 int32 = port.CellsAt(tc, (c*tcs)+13) - box0
			var eg0 int32 = box1 - port.CellsAt(tc, (c*tcs)+14)
			if sg0 > smax {
				smax = sg0
			}
			if sg0 < smin {
				smin = sg0
			}
			if eg0 > emax {
				emax = eg0
			}
			if eg0 < emin {
				emin = eg0
			}
			if tbAbs(sg0-eg0) > t {
				cen = 0
			}
		}
		c += 1
	}
	if (smax <= t) && ((emax - emin) > (2 * t)) {
		res = 1
	}
	if (res == 0) && ((emax <= t) && ((smax - smin) > (2 * t))) {
		res = 3
	}
	if (res == 0) && ((cen == 1) && ((smax - smin) > (2 * t))) {
		res = 2
	}
	return res
}

func tbHeadAlign(tb *port.Cells, k int32, c int32, colal int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The alignment of header cell c: against its cell box in a ruled table (and when it spans columns),
	// else against the extent of its column's BODY text (the header is not its own measure): centre or end when
	// the text is clear of the body's edges by 4t, start when it is flush and the column's body is start.
	var b int32 = k * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var cb int32 = c * tcs
	var col int32 = port.CellsAt(tc, cb+1)
	var bx0 int32 = port.CellsAt(tc, cb+4)
	var bx1 int32 = port.CellsAt(tc, cb+6)
	var j int32 = cfirst
	if port.CellsAt(tc, cb+9) == 0 {
		return 0
	}
	if (port.CellsAt(tb, b+5) != pfRuled) && (port.CellsAt(tc, cb+3) == 1) {
		bx0 = 2000000000
		bx1 = -2000000000
		for j < cend {
			if (port.CellsAt(tc, (j*tcs)+1) == col) && ((port.CellsAt(tc, (j*tcs)+3) == 1) && ((port.CellsAt(tc, j*tcs) >= port.CellsAt(tb, b+11)) && (port.CellsAt(tc, (j*tcs)+9) > 0))) {
				if port.CellsAt(tc, (j*tcs)+13) < bx0 {
					bx0 = port.CellsAt(tc, (j*tcs)+13)
				}
				if port.CellsAt(tc, (j*tcs)+14) > bx1 {
					bx1 = port.CellsAt(tc, (j*tcs)+14)
				}
			}
			j += 1
		}
		if bx0 > bx1 {
			return 0
		}
	}
	var t int32 = evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, cb+8)), evidence.WfSize()) / 4
	var sg0 int32 = port.CellsAt(tc, cb+13) - bx0
	var eg0 int32 = bx1 - port.CellsAt(tc, cb+14)
	if (tbAbs(sg0-eg0) <= t) && (tbMin(sg0, eg0) >= (4 * t)) {
		return 2
	}
	if (eg0 >= 0) && ((eg0 <= t) && (sg0 >= (4 * t))) {
		return 3
	}
	if (sg0 >= 0) && ((sg0 <= t) && ((colal == 1) && (eg0 >= 0))) {
		return 1
	}
	return 0
}

func tbAligns(tb *port.Cells, k int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// Set the `align` of every cell of table k: the body columns together, the header cells each, the foot
	// cells as their column.
	var b int32 = k * tagtable.Tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var ncols int32 = port.CellsAt(tb, b+8)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var nhead int32 = port.CellsAt(tb, b+11)
	var nfoot int32 = port.CellsAt(tb, b+12)
	var col int32 = 0
	var c int32 = 0
	var al int32 = 0
	for col < ncols {
		al = tbColAlign(tb, k, col, nhead, nrows-nfoot, wd, tc, tw)
		c = cfirst
		for c < cend {
			if (port.CellsAt(tc, (c*tcs)+1) == col) && (port.CellsAt(tc, (c*tcs)+3) == 1) {
				if port.CellsAt(tc, c*tcs) >= nhead {
					port.CellsSet(tc, (c*tcs)+11, al)
				} else {
					var ha int32 = tbHeadAlign(tb, k, c, al, wd, tc, tw)
					port.CellsSet(tc, (c*tcs)+11, ha)
				}
			}
			c += 1
		}
		col += 1
	}
	c = cfirst
	for c < cend {
		if (port.CellsAt(tc, c*tcs) < nhead) && (port.CellsAt(tc, (c*tcs)+3) > 1) {
			var ha int32 = tbHeadAlign(tb, k, c, 0, wd, tc, tw)
			port.CellsSet(tc, (c*tcs)+11, ha)
		}
		c += 1
	}
	return 0
}

var tbKw [81]int32 = [81]int32{
	5, 116, 97, 98, 108, 101, 0, 0, 0,
	3, 116, 97, 98, 0, 0, 0, 0, 0,
	7, 116, 97, 98, 101, 108, 108, 101, 0,
	7, 116, 97, 98, 108, 101, 97, 117, 0,
	5, 116, 97, 98, 108, 97, 0, 0, 0,
	6, 116, 97, 98, 101, 108, 97, 0, 0,
	7, 116, 97, 98, 101, 108, 108, 97, 0,
	5, 116, 97, 98, 101, 108, 0, 0, 0,
	6, 116, 97, 98, 101, 108, 108, 0, 0,
}

func tbLower(cp int32) int32 {
	if (cp >= 65) && (cp <= 90) {
		return cp + 32
	}
	return cp
}

func tbIsLabelWord(wd *port.Cells, et *port.Cells, w int32) bool {
	// Is the word a table keyword (any case, a trailing full stop ignored): Table, Tab., Tabelle, Tableau...
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var r int32 = 0
	var j int32 = 0
	var same int32 = 1
	if tl < 1 {
		return 0 == 1
	}
	if port.CellsAt(et, ts+(tl-1)) == 46 {
		tl -= 1
	}
	for r < 9 {
		if tbKw[r*9+0] == tl {
			same = 1
			j = 0
			for j < tl {
				if tbLower(port.CellsAt(et, ts+j)) != tbKw[r*9+(j+1)] {
					same = 0
				}
				j += 1
			}
			if same == 1 {
				return 1 == 1
			}
		}
		r += 1
	}
	return 0 == 1
}

func tbIsLabelNumber(wd *port.Cells, et *port.Cells, w int32) bool {
	// A table number: starts with a digit, or a capital letter and a digit (S1).
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	if tl < 1 {
		return 0 == 1
	}
	var c0 int32 = port.CellsAt(et, ts)
	if (c0 >= 48) && (c0 <= 57) {
		return 1 == 1
	}
	if (tl >= 2) && ((c0 >= 65) && (c0 <= 90)) {
		var c1 int32 = port.CellsAt(et, ts+1)
		return (c1 >= 48) && (c1 <= 57)
	}
	return 0 == 1
}

func tbLineLabel(wd *port.Cells, et *port.Cells, ln *port.Cells, l int32) bool {
	// Does line l start with a table keyword and a table number.
	var w0 int32 = evidence.LnGet(ln, l, evidence.LhFirst())
	if evidence.LnGet(ln, l, evidence.LhCount()) < 2 {
		return 0 == 1
	}
	return tbIsLabelWord(wd, et, w0) && tbIsLabelNumber(wd, et, w0+1)
}

func tbCaptionForNext(tb *port.Cells, k int32, ln *port.Cells, l int32, distance int32) bool {
	// D659: caption ownership is decided against all selected tables, before a preceding table claims a below-caption. Prefer the following table when its above-caption is at least as close.
	var q int32 = 0
	var b int32 = 0
	var d int32 = 0
	var h int32 = evidence.LnGet(ln, l, evidence.LhY1()) - evidence.LnGet(ln, l, evidence.LhY0())
	for q < tbRowsOf(tb, tagtable.Tbs) {
		b = q * tagtable.Tbs
		if (q != k) && (port.CellsAt(tb, b) == port.CellsAt(tb, k*tagtable.Tbs)) && (evidence.LnGet(ln, l, evidence.LhX0()) < port.CellsAt(tb, b+3)) && (evidence.LnGet(ln, l, evidence.LhX1()) > port.CellsAt(tb, b+1)) {
			d = port.CellsAt(tb, b+2) - evidence.LnGet(ln, l, evidence.LhY1())
			if (d >= -300) && ((d * 2) <= (h * 5)) && (tbAbs(d) <= distance) {
				return 1 == 1
			}
		}
		q += 1
	}
	return 1 == 0
}

func TbCaption(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, ln *port.Cells, l0 int32, l1 int32, tq *port.Cells) int32 {
	// Find the caption of table k among the unclaimed lines l0..l1: a line that starts with a table keyword
	// and a number, over the table or under it within two and a half line heights, preferring the one over it;
	// the lines on its baseline to its right and the lines under it that continue it are part of it. They are
	// claimed and their numbers pushed on `tq` (qfirst, qcount in the table's cells 14 and 15).
	var b int32 = k * tagtable.Tbs
	var tx0 int32 = port.CellsAt(tb, b+1)
	var ty0 int32 = port.CellsAt(tb, b+2)
	var tx1 int32 = port.CellsAt(tb, b+3)
	var ty1 int32 = port.CellsAt(tb, b+4)
	var l int32 = l0
	var best int32 = -1
	var bestd int32 = 2000000000
	var above int32 = 0
	for l < l1 {
		if evidence.LnGet(ln, l, 15) == 0 {
			if tbLineLabel(wd, et, ln, l) {
				if (evidence.LnGet(ln, l, evidence.LhX0()) < tx1) && (evidence.LnGet(ln, l, evidence.LhX1()) > tx0) {
					var lht int32 = evidence.LnGet(ln, l, evidence.LhY1()) - evidence.LnGet(ln, l, evidence.LhY0())
					var da int32 = ty0 - evidence.LnGet(ln, l, evidence.LhY1())
					var db int32 = evidence.LnGet(ln, l, evidence.LhY0()) - ty1
					if (da >= -300) && ((da * 2) <= (lht * 5)) {
						if tbAbs(da) < bestd {
							best = l
							bestd = tbAbs(da)
							above = 1
						}
					}
					if (db >= -300) && (((db * 2) <= (lht * 5)) && (above == 0)) && !tbCaptionForNext(tb, k, ln, l, tbAbs(db)) {
						if tbAbs(db) < bestd {
							best = l
							bestd = tbAbs(db)
						}
					}
				}
			}
		}
		l += 1
	}
	if best < 0 {
		return 0
	}
	port.CellsSet(tb, b+14, port.CellsLen(tq))
	port.CellsPush(tq, best)
	evidence.LnSet(ln, best, 15, tbHeld+k)
	var h int32 = evidence.LnGet(ln, best, evidence.LhY1()) - evidence.LnGet(ln, best, evidence.LhY0())
	var curx1 int32 = evidence.LnGet(ln, best, evidence.LhX1())
	var cury1 int32 = evidence.LnGet(ln, best, evidence.LhY1())
	var more int32 = 1
	var rounds int32 = 0
	var pick int32 = -1
	l = l0
	for l < l1 {
		if evidence.LnGet(ln, l, 15) == 0 {
			if (evidence.LnGet(ln, l, evidence.LhX0()) > (curx1 - 100)) && ((evidence.LnGet(ln, l, evidence.LhX0()) - curx1) <= (2 * h)) {
				if tbAbs(evidence.LnGet(ln, l, evidence.LhBy0())-evidence.LnGet(ln, best, evidence.LhBy0())) <= (h / 3) {
					port.CellsPush(tq, l)
					evidence.LnSet(ln, l, 15, tbHeld+k)
					curx1 = evidence.LnGet(ln, l, evidence.LhX1())
				}
			}
		}
		l += 1
	}
	for (more == 1) && (rounds < 6) {
		more = 0
		rounds += 1
		pick = -1
		l = l0
		for l < l1 {
			if evidence.LnGet(ln, l, 15) == 0 {
				if (evidence.LnGet(ln, l, evidence.LhY0()) >= (cury1 - 200)) && ((evidence.LnGet(ln, l, evidence.LhY0()) - cury1) <= ((h * 3) / 5)) {
					if (evidence.LnGet(ln, l, evidence.LhX0()) < tx1) && (evidence.LnGet(ln, l, evidence.LhX1()) > tx0) {
						if !tbLineLabel(wd, et, ln, l) {
							if evidence.LnGet(ln, l, evidence.LhY1()) < (ty0 + 300) {
								if pick < 0 {
									pick = l
								}
							}
						}
					}
				}
			}
			l += 1
		}
		if (pick >= 0) && (above == 1) {
			port.CellsPush(tq, pick)
			evidence.LnSet(ln, pick, 15, tbHeld+k)
			cury1 = evidence.LnGet(ln, pick, evidence.LhY1())
			more = 1
		}
	}
	port.CellsSet(tb, b+15, port.CellsLen(tq)-port.CellsAt(tb, b+14))
	return 1
}

func tbReject(tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells, nt int32, c0 int32, w0 int32, x0 int32) int32 {
	// Forget the candidate that was just built: every arena goes back to the length it had.
	port.CellsDrop(tb, nt*tagtable.Tbs)
	port.CellsDrop(tc, c0*tcs)
	port.CellsDrop(tw, w0)
	port.CellsDrop(tx, x0)
	return 0
}

func tbTabularRows(tb *port.Cells, k int32, tc *port.Cells) int32 {
	// How many rows of table k have two cells or more with text.
	var b int32 = k * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var row int32 = -1
	var cnt int32 = 0
	var total int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) != row {
			if cnt >= 2 {
				total += 1
			}
			row = port.CellsAt(tc, c*tcs)
			cnt = 0
		}
		if port.CellsAt(tc, (c*tcs)+9) > 0 {
			cnt += 1
		}
		c += 1
	}
	if cnt >= 2 {
		total += 1
	}
	return total
}

func tbLeadSingle(tb *port.Cells, k int32, tc *port.Cells) int32 {
	// P12.2: how many rows at the top of table k (at most two) have one cell with text: a spanning header (`December 31,` over the year columns, taken
	// in by `tb-head-reach`), a row that is no less a row of the table for not having two cells. `tb-score` leaves them out of the count of its rows.
	var b int32 = k * tagtable.Tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var row int32 = 0
	var cnt int32 = 0
	var lead int32 = 0
	var done int32 = 0
	for (c < cend) && (done == 0) {
		if port.CellsAt(tc, c*tcs) != row {
			if cnt == 1 {
				lead += 1
			} else {
				done = 1
			}
			row = port.CellsAt(tc, c*tcs)
			cnt = 0
		}
		if port.CellsAt(tc, (c*tcs)+9) > 0 {
			cnt += 1
		}
		c += 1
	}
	if (done == 0) && (cnt == 1) {
		lead += 1
	}
	return tbMin(lead, 2)
}

func tbLowc(c int32) int32 {
	// D583 (smoke review B issue 14): 1 for a lower case letter of a cased script: Latin (ASCII and Latin-1), Greek, Cyrillic. A cell of two words or more that begins with one is text set in chunks,
	// whatever the script (the ASCII letters alone made a Russian paragraph's lines a table).
	if (c >= 97) && (c <= 122) {
		return 1
	}
	if (c >= 223) && (c <= 255) && (c != 247) {
		return 1
	}
	if (c >= 945) && (c <= 969) {
		return 1
	}
	if (c >= 1072) && (c <= 1103) {
		return 1
	}
	return 0
}

func tbMostlyText(wd *port.Cells, tc *port.Cells, tw *port.Cells, cfirst int32, cend int32) bool {
	// D632: stable born-digital word boxes support the categorical grid; an OCR-only grid still needs the pre-existing table evidence.
	var c int32 = cfirst
	var j int32 = 0
	var n int32 = 0
	var textwords int32 = 0
	for c < cend {
		j = 0
		for j < port.CellsAt(tc, (c*tcs)+9) {
			n += 1
			if (evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+j), evidence.WfSrc()) & model.SrText()) != 0 {
				textwords += 1
			}
			j += 1
		}
		c += 1
	}
	return (n > 0) && ((textwords * 4) >= (n * 3))
}

func tbScore(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The score (0 to 1000, 0 = not a table) of text-based candidate k of its profile (SPEC 10.5): prose in
	// columns is not a table, so cells that are long, or that end like sentences, refuse it. The whitespace
	// profile has no rules or fills to vouch for it and asks for more: numeric columns, a header, or a dense grid of at least four short categorical columns.
	var b int32 = k * tagtable.Tbs
	var prof int32 = port.CellsAt(tb, b+5)
	var ncols int32 = port.CellsAt(tb, b+8)
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var ne int32 = 0
	var nw int32 = 0
	var nlong int32 = 0
	var nend int32 = 0
	var nprose int32 = 0
	var score int32 = 0
	for c < cend {
		var cn int32 = port.CellsAt(tc, (c*tcs)+9)
		if cn > 0 {
			ne += 1
			nw += cn
			if cn > 8 {
				nlong += 1
			}
			if cn >= 2 {
				var fw int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8))
				var lw2 int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+(cn-1))
				var c0 int32 = port.CellsAt(et, evidence.WdGet(wd, fw, evidence.HdTstart()))
				var ts2 int32 = evidence.WdGet(wd, lw2, evidence.HdTstart())
				var tl2 int32 = evidence.WdGet(wd, lw2, evidence.HdTlen())
				if tbLowc(c0) == 1 {
					nprose += 1
				}
				if (tl2 > 1) && (port.CellsAt(et, ts2+(tl2-1)) == 45) {
					nprose += 1
				}
			}
			if cn >= 3 {
				var lw int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+(cn-1))
				var ts int32 = evidence.WdGet(wd, lw, evidence.HdTstart())
				var tl int32 = evidence.WdGet(wd, lw, evidence.HdTlen())
				if (tl > 0) && (port.CellsAt(et, ts+(tl-1)) == 46) {
					nend += 1
				}
			}
		}
		c += 1
	}
	if ne < 4 {
		return 0
	}
	if (nprose * 10) > (ne * 3) {
		return 0
	}
	if (prof == pfWhitespace) && (((port.CellsAt(tb, b+31) & 1) == 0) && ((ne * 100) < ((nrows * ncols) * 55))) {
		return 0
	}
	if (ne * 100) < ((nrows * ncols) * 35) {
		return 0
	}
	if (nend * 5) > (ne * 2) {
		return 0
	}
	if (nlong * 5) > ne {
		return 0
	}
	if prof == pfWhitespace {
		if (nw * 10) > (ne * 40) {
			return 0
		}
		score = 400
		if ncols >= 3 {
			score += 100
		}
		if tbMax(tbNumCols(tb, k, 1, wd, et, tc, tw), tbNumCols(tb, k, 0, wd, et, tc, tw)) >= 1 {
			score += 100
		}
		if tbHeadRows(tb, k, wd, et, tc, tw) >= 1 {
			score += 100
		}
		if nrows >= 4 {
			score += 50
		}
		// D632: a dense grid of at least four short categorical columns needs neither a numeric column nor a bold heading; the prose checks above still apply.
		if (score < 600) && ((ncols >= 4) && ((nrows >= 4) && (((ne * 5) >= ((nrows * ncols) * 4)) && tbMostlyText(wd, tc, tw, cfirst, cend)))) {
			score = 600
		}
		// D633: a three-row summary has no header: count its first amount as well as the other two, without changing a headed table's numeric-column test.
		if (ncols == 2) && ((nrows >= 3) && ((tbMax(tbNumCols(tb, k, 1, wd, et, tc, tw), tbNumCols(tb, k, 0, wd, et, tc, tw)) == 1) && ((nw * 10) <= (ne * 25)))) {
			score += 100
		}
		if score < 600 {
			return 0
		}
		return score
	}
	if (nw * 10) > (ne * 80) {
		return 0
	}
	if prof == pfPartial {
		return 800 + ((90 * tbTabularRows(tb, k, tc)) / tbMax(1, nrows-tbLeadSingle(tb, k, tc)))
	}
	return 750 + ((40 * tbTabularRows(tb, k, tc)) / tbMax(1, nrows))
}

func tbBodyRow(rw *port.Cells, nr int32, y0 int32) int32 {
	// The first row whose centre is below the top rule y0 (nr when none).
	var ra int32 = 0
	for (ra < nr) && (((port.CellsAt(rw, (ra*rws)+6) + port.CellsAt(rw, (ra*rws)+7)) / 2) < y0) {
		ra += 1
	}
	return ra
}

func tbBackNear(rw *port.Cells, r int32, below int32) int32 {
	// 1 when row r, directly above row `below`, is a tabular row (two chunks or more) a pitch of at most 2.4 sizes of `below` above it:
	// the rule of the first versions for a header the top rule leaves out.
	if port.CellsAt(rw, (r*rws)+9) < 2 {
		return 0
	}
	if (10 * (port.CellsAt(rw, (below*rws)+2) - port.CellsAt(rw, (r*rws)+2))) <= (24 * port.CellsAt(rw, (below*rws)+3)) {
		return 1
	}
	return 0
}

func tbAligned(rw *port.Cells, sg *port.Cells, r int32, rb int32, nr int32) int32 {
	// 1 when the chunks of row r line up with the body's (D557): at least two of them, and three in five, have a left or a right edge
	// within `TB_HEAD_TOL` of an edge of a chunk of the body rows rb..nr (twelve of them at most; never row r itself, which D559's
	// `tb-gap-foreign` and `tb-tail-end` ask about among the rows around it).
	var nch int32 = port.CellsAt(rw, (r*rws)+9)
	var sf int32 = port.CellsAt(rw, (r*rws)+8)
	var bend int32 = tbMin(nr, rb+12)
	var s int32 = 0
	var hit int32 = 0
	var b int32 = 0
	var q int32 = 0
	var found int32 = 0
	for s < nch {
		found = 0
		b = rb
		for (b < bend) && (found == 0) {
			q = 0
			for (q < port.CellsAt(rw, (b*rws)+9)) && (found == 0) {
				var hs int32 = sf + s
				var bs int32 = port.CellsAt(rw, (b*rws)+8) + q
				if (b != r) && (tbAbs(port.CellsAt(sg, (hs*sgs)+1)-port.CellsAt(sg, (bs*sgs)+1)) <= tbHeadTol) {
					found = 1
				}
				if (b != r) && (tbAbs(port.CellsAt(sg, (hs*sgs)+2)-port.CellsAt(sg, (bs*sgs)+2)) <= tbHeadTol) {
					found = 1
				}
				q += 1
			}
			b += 1
		}
		hit += found
		s += 1
	}
	if hit < 2 {
		return 0
	}
	if (hit * 5) >= (nch * 3) {
		return 1
	}
	return 0
}

func tbBackAligned(rw *port.Cells, sg *port.Cells, r int32, below int32, rb int32, nr int32) int32 {
	// 1 when row r, directly above row `below`, is a tabular row at most `TB_HEAD_PITCH` tenths of a size of `below` above it whose
	// chunks line up with the body's columns (`tb-aligned`): a header in a smaller or another type, set further from the rule than
	// a line of text is (D557).
	if port.CellsAt(rw, (r*rws)+9) < 2 {
		return 0
	}
	if (10 * (port.CellsAt(rw, (below*rws)+2) - port.CellsAt(rw, (r*rws)+2))) > (tbHeadPitch * port.CellsAt(rw, (below*rws)+3)) {
		return 0
	}
	return tbAligned(rw, sg, r, rb, nr)
}

func tbFirstRow(rm *port.Cells, rw *port.Cells, sg *port.Cells, nr int32, y0 int32, align int32) int32 {
	// The first row of a partial candidate: the first row whose centre is below the top rule y0, and the
	// tabular rows (at most three) directly above it, which are the header when the rule is the one under it: a row close above (at
	// most 2.4 sizes, `tb-back-near`) or, when `align` is 1 (y0 is the top rule of its whole chain: above it is nothing of the table's
	// own), one that lines up with the body's columns whatever its size and pitch (`tb-back-aligned`). P12.2: and then, when `align` is 1, the
	// one-chunk rows over a short rule (`tb-head-reach`: `December 31,` over the years).
	var rb int32 = tbBodyRow(rw, nr, y0)
	var ra int32 = rb
	var n int32 = 0
	for (ra > 0) && ((ra < nr) && ((n < 3) && ((tbBackNear(rw, ra-1, ra) == 1) || ((align == 1) && (tbBackAligned(rw, sg, ra-1, ra, rb, nr) == 1))))) {
		ra -= 1
		n += 1
	}
	if (align == 1) && (ra < nr) {
		ra = tbHeadReach(rm, rw, sg, ra, nr-1)
	}
	return ra
}

func tbFirstForced(rw *port.Cells, nr int32, y0 int32, ra int32) int32 {
	// 1 when a row of ra.. above the top rule y0 was taken for the header by alignment alone, not by being close (D557). P12.2: a row of one chunk
	// over a short rule (`tb-head-reach`) is no such row: the header rows are the bold ones, a spanning label and the years under it.
	var rb int32 = tbBodyRow(rw, nr, y0)
	var r int32 = ra
	for r < rb {
		if (tbBackNear(rw, r, r+1) == 0) && (port.CellsAt(rw, (r*rws)+9) >= 2) {
			return 1
		}
		r += 1
	}
	return 0
}

func tbExtend(wd *port.Cells, w0 int32, w1 int32, rw *port.Cells, sg *port.Cells, ra int32, nr int32, edge int32, dir int32, rm *port.Cells, pr *port.Cells, ry *port.Cells) int32 {
	// D557: how far the rows ra..nr of a partial candidate go on the side `dir` (1 right, -1 left) of x `edge` (the candidate's edge there,
	// which the rules gave): over the words on the rows' own baselines that continue them. A column of cells the producer left unruled (the amounts
	// of a statement whose row borders stop at the description) is the table's. The words are followed while each starts within the table's own widest
	// gap (not under two sizes, not over twelve) of the reach so far: a wider one is a gutter. A vertical rule that spans three in five of the rows
	// stops them, and so does a horizontal one that goes on past the edge on the rows' height (another table's); at least three in five of the
	// rows must have such a word. Answers the new edge, or `edge`.
	var n int32 = nr - ra
	var size int32 = port.CellsAt(rw, (ra*rws)+3)
	var nrl int32 = tbRowsOf(rm, rls)
	var e int32 = dir * edge
	var widest int32 = 0
	var gapmax int32 = 0
	var ytop int32 = 2000000000
	var ybot int32 = -2000000000
	var limit int32 = 2000000000
	var reach int32 = e
	var changed int32 = 1
	var r int32 = 0
	var s int32 = 0
	var w int32 = 0
	var i int32 = 0
	var hit int32 = 0
	var lo int32 = 0
	var hi int32 = 0
	var p int32 = 0
	var far int32 = 0
	var cx int32 = 0
	var cy int32 = 0
	var ov int32 = 0
	if n < 3 {
		return edge
	}
	r = ra
	for r < nr {
		s = 0
		for s < (port.CellsAt(rw, (r*rws)+9) - 1) {
			var a int32 = port.CellsAt(rw, (r*rws)+8) + s
			if (port.CellsAt(sg, ((a+1)*sgs)+1) - port.CellsAt(sg, (a*sgs)+2)) > widest {
				widest = port.CellsAt(sg, ((a+1)*sgs)+1) - port.CellsAt(sg, (a*sgs)+2)
			}
			s += 1
		}
		if port.CellsAt(rw, (r*rws)+6) < ytop {
			ytop = port.CellsAt(rw, (r*rws)+6)
		}
		if port.CellsAt(rw, (r*rws)+7) > ybot {
			ybot = port.CellsAt(rw, (r*rws)+7)
		}
		r += 1
	}
	gapmax = widest
	if gapmax < (2 * size) {
		gapmax = 2 * size
	}
	if gapmax > (12 * size) {
		gapmax = 12 * size
	}
	// What stops them: a vertical rule spanning the rows, another table's horizontal rule going on past the edge.
	i = 0
	for i < nrl {
		p = port.CellsAt(rm, (i*rls)+1)
		lo = port.CellsAt(rm, (i*rls)+2)
		hi = port.CellsAt(rm, (i*rls)+3)
		if port.CellsAt(rm, i*rls) == 1 {
			ov = tbMin(hi, ybot) - tbMax(lo, ytop)
			if ((dir * p) > e) && ((ov * 5) >= ((ybot - ytop) * 3)) {
				if (dir * p) < limit {
					limit = dir * p
				}
			}
		} else if (p >= ytop) && (p <= ybot) {
			if dir > 0 {
				far = hi
			} else {
				far = lo
			}
			if (dir * far) > (e + posTol) {
				return edge
			}
		}
		i += 1
	}
	// The words of the rows' baselines on that side, as (word, row) pairs in `pr`.
	port.CellsDrop(pr, 0)
	w = w0
	for w < w1 {
		if (evidence.WdGet(wd, w, evidence.HdTlen()) > 0) && tbUpright(wd, w) {
			cx = dir * ((evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2)
			cy = (evidence.WdGet(wd, w, evidence.HdY0()) + evidence.WdGet(wd, w, evidence.HdY1())) / 2
			if (cx > e) && (cx < limit) {
				r = ra
				for r < nr {
					if (cy >= port.CellsAt(rw, (r*rws)+6)) && (cy <= port.CellsAt(rw, (r*rws)+7)) {
						port.CellsPush(pr, w)
						port.CellsPush(pr, r)
						r = nr
					}
					r += 1
				}
			}
		}
		w += 1
	}
	for changed == 1 {
		changed = 0
		i = 0
		for i < (port.CellsLen(pr) / 2) {
			w = port.CellsAt(pr, i*2)
			if dir > 0 {
				lo = evidence.WdGet(wd, w, evidence.HdX0())
				hi = evidence.WdGet(wd, w, evidence.HdX1())
			} else {
				lo = 0 - evidence.WdGet(wd, w, evidence.HdX1())
				hi = 0 - evidence.WdGet(wd, w, evidence.HdX0())
			}
			if (lo <= (reach + gapmax)) && (hi > reach) {
				reach = hi
				changed = 1
			}
			i += 1
		}
	}
	if reach <= e {
		return edge
	}
	// Rows that have a word inside the reach: three in five of them.
	port.CellsDrop(ry, 0)
	r = 0
	for r < n {
		port.CellsPush(ry, 0)
		r += 1
	}
	i = 0
	for i < (port.CellsLen(pr) / 2) {
		w = port.CellsAt(pr, i*2)
		if dir > 0 {
			hi = evidence.WdGet(wd, w, evidence.HdX1())
		} else {
			hi = 0 - evidence.WdGet(wd, w, evidence.HdX0())
		}
		if hi <= reach {
			port.CellsSet(ry, port.CellsAt(pr, (i*2)+1)-ra, 1)
		}
		i += 1
	}
	r = 0
	for r < n {
		hit += port.CellsAt(ry, r)
		r += 1
	}
	if (hit * 5) < (n * 3) {
		return edge
	}
	return dir * reach
}

func tbPartialBuild(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, page int32, ex0 int32, ex1 int32, ya int32, yb int32, align int32, rm *port.Cells, kc *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// One partial candidate over the extent ex0..ex1: the words between the rules at ya and yb (and the rows directly above ya, the header),
	// columns from their channels; kept when it scores. The rows are left in `wl rw sg`. Answers the candidate, or -1 (nothing is left of it).
	var nr int32 = tbRows(wd, et, w0, w1, ex0-posTol, ya-9000, ex1+posTol, yb, wl, rw, sg)
	var ra int32 = tbFirstRow(rm, rw, sg, nr, ya, align)
	var nt int32 = tbRowsOf(tb, tagtable.Tbs)
	var c0 int32 = tbRowsOf(tc, tcs)
	var wl0 int32 = port.CellsLen(tw)
	var xl0 int32 = port.CellsLen(tx)
	if (nr - ra) >= 3 {
		var t int32 = tbTextGrid(wd, et, wl, rw, sg, rm, kc, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, ra, nr, pfPartial, 850, 0, ex0, ya, ex1, yb)
		if t >= 0 {
			var sc int32 = tbScore(tb, t, wd, et, tc, tw)
			var rb int32 = tbBodyRow(rw, nr, ya)
			if sc == 0 {
				tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
			} else {
				port.CellsSet(tb, (t*tagtable.Tbs)+6, sc)
				// Rows taken for the header by alignment alone are the header (the table rows they make: a wrapped label is one).
				if (ra < rb) && (tbFirstForced(rw, nr, ya, ra) == 1) {
					port.CellsSet(tb, (t*tagtable.Tbs)+22, port.CellsAt(rmap, (rb-1)-ra)+1)
				}
				return t
			}
		}
	}
	return -1
}

func tbPartialTry(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, page int32, ex0 int32, ex1 int32, ya int32, yb int32, ychain int32, rm *port.Cells, kc *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// One partial candidate: the words between the rules at ya and yb (and the tabular rows directly above ya),
	// columns from their channels; kept when it scores. D557: when the rows go on past the ends of the rules (`tb-extend`), the
	// candidate is built again over the wider extent, and kept if it scores; if not the narrower one stands. `ychain` is the top rule of the
	// whole chain: only when ya is it can a header be sought by alignment (above any other rule lie the table's own rows).
	var nt int32 = tbRowsOf(tb, tagtable.Tbs)
	var c0 int32 = tbRowsOf(tc, tcs)
	var wl0 int32 = port.CellsLen(tw)
	var xl0 int32 = port.CellsLen(tx)
	var align int32 = 0
	if ya <= (ychain + posTol) {
		align = 1
	}
	var t int32 = tbPartialBuild(wd, et, w0, w1, page, ex0, ex1, ya, yb, align, rm, kc, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
	if t >= 0 {
		var nr int32 = tbRowsOf(rw, rws)
		var ra int32 = tbFirstRow(rm, rw, sg, nr, ya, align)
		var nx1 int32 = tbExtend(wd, w0, w1, rw, sg, ra, nr, ex1, 1, rm, pr, ry)
		var nx0 int32 = tbExtend(wd, w0, w1, rw, sg, ra, nr, ex0, -1, rm, pr, ry)
		if (nx1 > ex1) || (nx0 < ex0) {
			tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
			if tbPartialBuild(wd, et, w0, w1, page, nx0, nx1, ya, yb, align, rm, kc, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx) < 0 {
				tbPartialBuild(wd, et, w0, w1, page, ex0, ex1, ya, yb, align, rm, kc, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
			}
		}
	}
	return 0
}

func tbGapForeign(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, ex0 int32, ex1 int32, ytop int32, last int32, yj int32, wl *port.Cells, rw *port.Cells, sg *port.Cells) int32 {
	// D559: 1 when what lies between the rules at `last` and `yj`, in the extent ex0..ex1, is not the chain's own (the chain begins at the rule
	// ytop and has its rows down to `last`): a heading or a label (a row in type `TB_GAP_SIZE` hundredths of the rows' or more), a row of
	// two chunks or more that lines up with no other row's columns (another grid's; the first twelve rows are asked), or a band of white deeper than `TB_GAP_BAND`
	// tenths of a size between a row and the one before it (the last of the chain's own included). A chain of rules is one table; two tables whose
	// rules are near enough to chain are two.
	var nr int32 = tbRows(wd, et, w0, w1, ex0-posTol, ytop, ex1+posTol, yj, wl, rw, sg)
	var g int32 = 0
	var r int32 = 0
	var sum int64 = int64(0)
	var size int32 = 0
	for (g < nr) && (((port.CellsAt(rw, (g*rws)+6) + port.CellsAt(rw, (g*rws)+7)) / 2) < last) {
		g += 1
	}
	if (g == 0) || (g >= nr) {
		return 0
	}
	for r < g {
		sum = sum + int64(port.CellsAt(rw, (r*rws)+3))
		r += 1
	}
	size = int32(sum / int64(g))
	r = g
	for r < nr {
		if (100 * port.CellsAt(rw, (r*rws)+3)) >= (tbGapSize * size) {
			return 1
		}
		if (port.CellsAt(rw, (r*rws)+9) >= 2) && (tbAligned(rw, sg, r, 0, nr) == 0) {
			return 1
		}
		if (10 * (port.CellsAt(rw, (r*rws)+6) - port.CellsAt(rw, ((r-1)*rws)+7))) > (tbGapBand * size) {
			return 1
		}
		r += 1
	}
	return 0
}

func tbTailEnd(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, ex0 int32, ex1 int32, ytop int32, ybot int32, wl *port.Cells, rw *port.Cells, sg *port.Cells) int32 {
	// D559: the bottom of a chain of rules that begins at ytop and ends at ybot, with the rows below its last rule that are its own: a table
	// whose last row has no border under it (a statement's closing balance, a summary's total). A row of two chunks or more that lines up with
	// the rows' columns (`tb-aligned`), at most `TB_HEAD_PITCH` tenths of its size and `TB_TAIL_PITCH` tenths of the rows' mean pitch under
	// the row before it, beginning in the rows' first column (within `TB_HEAD_TOL` of their left edge: a summary block in the last columns, an
	// invoice's totals, is a table of its own), and at most `TB_TAIL_ROWS` of them; the chain needs two rows of its own to have a pitch and columns to line up
	// with. Answers ybot, or the bottom of the last such row.
	var nr int32 = tbRows(wd, et, w0, w1, ex0-posTol, ytop, ex1+posTol, ybot+tbTailReach, wl, rw, sg)
	var g int32 = 0
	var r int32 = 0
	var taken int32 = 0
	var res int32 = ybot
	var left int32 = 0
	var mean int32 = 0
	var lim int32 = 0
	var pitch int32 = 0
	for (g < nr) && (((port.CellsAt(rw, (g*rws)+6) + port.CellsAt(rw, (g*rws)+7)) / 2) < ybot) {
		g += 1
	}
	if (g < 2) || (g >= nr) {
		return ybot
	}
	mean = (port.CellsAt(rw, ((g-1)*rws)+2) - port.CellsAt(rw, 2)) / (g - 1)
	r = 0
	left = 2000000000
	for r < g {
		if port.CellsAt(rw, (r*rws)+4) < left {
			left = port.CellsAt(rw, (r*rws)+4)
		}
		r += 1
	}
	r = g
	for (r < nr) && (taken < tbTailRows) {
		pitch = port.CellsAt(rw, (r*rws)+2) - port.CellsAt(rw, ((r-1)*rws)+2)
		if port.CellsAt(rw, (r*rws)+9) < 2 {
			return res
		}
		// A row of the table begins in its first column; a summary block under it (an invoice's totals) stands in the last columns.
		if tbAbs(port.CellsAt(rw, (r*rws)+4)-left) > tbHeadTol {
			return res
		}
		if (10 * pitch) > (tbHeadPitch * port.CellsAt(rw, (r*rws)+3)) {
			return res
		}
		// P12.2: the first row under the last rule may stand a blank pitch from the row above it: the rule between them says it is the table's total.
		lim = tbTailPitch
		if r == g {
			lim = tbTailBlank
		}
		if (mean > 0) && ((10 * pitch) > (lim * mean)) {
			return res
		}
		if tbAligned(rw, sg, r, 0, g) == 0 {
			return res
		}
		res = port.CellsAt(rw, (r*rws)+7)
		taken += 1
		r += 1
	}
	return res
}

func tbPartialPage(rm *port.Cells, kc *port.Cells, page int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, used *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// Chains of horizontal rules of one extent (booktabs: top, mid, bottom) are partial candidates: the
	// words between the first and the last rule, columns from the channels of their text. D559: a chain ends where a gap holds what is not
	// the table's (`tb-gap-foreign`: a heading, another grid, a band of white), and takes the rows under its last rule that are (`tb-tail-end`).
	var n int32 = tbRowsOf(rm, rls)
	var nh int32 = 0
	var i int32 = 0
	var j int32 = 0
	var pgap int32 = 0
	var ytail int32 = 0
	var cnt int32 = 0
	var ex0 int32 = 0
	var ex1 int32 = 0
	var m int32 = 0
	var last int32 = 0
	for (nh < n) && (port.CellsAt(rm, nh*rls) == 0) {
		nh += 1
	}
	port.CellsDrop(used, 0)
	for i < nh {
		port.CellsPush(used, 0)
		i += 1
	}
	i = 0
	for i < nh {
		if (port.CellsAt(used, i) == 0) && ((port.CellsAt(rm, (i*rls)+3) - port.CellsAt(rm, (i*rls)+2)) >= 3000) {
			cnt = 1
			pgap = 0
			ex0 = port.CellsAt(rm, (i*rls)+2)
			ex1 = port.CellsAt(rm, (i*rls)+3)
			last = port.CellsAt(rm, (i*rls)+1)
			port.CellsSet(used, i, 1)
			port.CellsPush(used, port.CellsAt(rm, (i*rls)+1))
			j = i + 1
			for (j < nh) && ((port.CellsAt(rm, (j*rls)+1) - last) <= 30000) {
				if port.CellsAt(used, j) == 0 {
					var a0 int32 = port.CellsAt(rm, (j*rls)+2)
					var a1 int32 = port.CellsAt(rm, (j*rls)+3)
					var ov int32 = tbMin(ex1, a1) - tbMax(ex0, a0)
					var lj int32 = a1 - a0
					if (lj >= 2000) && (((ov * 10) >= (lj * 6)) && ((ov * 10) >= ((ex1 - ex0) * 3))) {
						if (cnt >= 2) && ((tbBoxBreak(rm, ex0, ex1, port.CellsAt(rm, (i*rls)+1), last, port.CellsAt(rm, (j*rls)+1)) == 1) || (((2 * (port.CellsAt(rm, (j*rls)+1) - last)) > (3 * pgap)) && (tbGapForeign(wd, et, w0, w1, ex0, ex1, port.CellsAt(rm, (i*rls)+1), last, port.CellsAt(rm, (j*rls)+1), wl, rw, sg) == 1))) {
							j = nh
						} else {
							pgap = port.CellsAt(rm, (j*rls)+1) - last
							cnt += 1
							last = port.CellsAt(rm, (j*rls)+1)
							if a0 < ex0 {
								ex0 = a0
							}
							if a1 > ex1 {
								ex1 = a1
							}
							port.CellsSet(used, j, 1)
							port.CellsPush(used, port.CellsAt(rm, (j*rls)+1))
						}
					}
				}
				j += 1
			}
			if cnt >= 2 {
				ytail = tbTailEnd(wd, et, w0, w1, ex0, ex1, port.CellsAt(rm, (i*rls)+1), last, wl, rw, sg)
				tbPartialTry(wd, et, w0, w1, page, ex0, ex1, port.CellsAt(rm, (i*rls)+1), ytail, port.CellsAt(rm, (i*rls)+1), rm, kc, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
				if cnt >= 3 {
					m = nh
					for (m + 1) < port.CellsLen(used) {
						tbPartialTry(wd, et, w0, w1, page, ex0, ex1, port.CellsAt(used, m), port.CellsAt(used, m+1), port.CellsAt(rm, (i*rls)+1), rm, kc, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
						m += 1
					}
				}
			}
			port.CellsDrop(used, nh)
		}
		i += 1
	}
	return 0
}

func tbBands(fl *port.Cells, so *port.Cells, bd *port.Cells) int32 {
	// The page's fills (`fl`) grouped into bands of one top and bottom (`bd`, stride 6: y0 y1 x0 x1 colour n),
	// in order of their tops. Answers how many bands.
	var n int32 = tbRowsOf(fl, 6)
	var i int32 = 0
	port.CellsDrop(so, 0)
	port.CellsDrop(bd, 0)
	for i < n {
		port.CellsPush(so, i)
		i += 1
	}
	tbSortIdx(so, fl, 6, 1, 0)
	i = 0
	for i < n {
		var f int32 = port.CellsAt(so, i)
		var x0 int32 = port.CellsAt(fl, f*6)
		var y0 int32 = port.CellsAt(fl, (f*6)+1)
		var x1 int32 = port.CellsAt(fl, (f*6)+2)
		var y1 int32 = port.CellsAt(fl, (f*6)+3)
		var nb int32 = tbRowsOf(bd, 6)
		if (nb > 0) && ((tbAbs(y0-port.CellsAt(bd, (nb-1)*6)) <= 150) && ((tbAbs(y1-port.CellsAt(bd, ((nb-1)*6)+1)) <= 150) && (x0 <= (port.CellsAt(bd, ((nb-1)*6)+3) + 300)))) {
			var lb int32 = (nb - 1) * 6
			if x0 < port.CellsAt(bd, lb+2) {
				port.CellsSet(bd, lb+2, x0)
			}
			if x1 > port.CellsAt(bd, lb+3) {
				port.CellsSet(bd, lb+3, x1)
			}
			port.CellsSet(bd, lb+5, port.CellsAt(bd, lb+5)+1)
		} else {
			port.CellsPush(bd, y0)
			port.CellsPush(bd, y1)
			port.CellsPush(bd, x0)
			port.CellsPush(bd, x1)
			port.CellsPush(bd, port.CellsAt(fl, (f*6)+4))
			port.CellsPush(bd, 1)
		}
		i += 1
	}
	return tbRowsOf(bd, 6)
}

func tbBandMember(bd *port.Cells, used *port.Cells, b0 int32, b1 int32, y int32) int32 {
	// The band of b0..b1 that belongs to the stack being built (used = 2) and whose top and bottom hold y.
	var i int32 = b0
	for i <= b1 {
		if (port.CellsAt(used, i) == 2) && ((y >= port.CellsAt(bd, i*6)) && (y <= port.CellsAt(bd, (i*6)+1))) {
			return i
		}
		i += 1
	}
	return -1
}

func tbBandHeader(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, sx0 int32, sx1 int32, y0 int32, gap int32, wl *port.Cells, rw *port.Cells, sg *port.Cells) int32 {
	// The top of a stack of zebra bands that begins at y0 and whose bands are `gap` apart, with the row above it: a header
	// is unshaded (the zebra's first stripe is the plain one), so it is no band, and the stack's own extent would leave it out
	// of the table. The row is the one baseline row, cut in two chunks or more, whose words are within a gap and a quarter
	// above y0; answers its top when there is one, y0 when there is not (D503).
	if gap <= 0 {
		return y0
	}
	var hy0 int32 = y0 - (gap + (gap / 4))
	var nh int32 = tbRows(wd, et, w0, w1, sx0, hy0, sx1, y0-1, wl, rw, sg)
	if (nh == 1) && (port.CellsAt(rw, 9) >= 2) {
		return hy0
	}
	return y0
}

func tbShadedPage(fl *port.Cells, page int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, rm *port.Cells, kc *port.Cells, bd *port.Cells, used *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// Stacks of three or more bands of one extent, each starting where the one before ended or one row
	// later, with two colours or a gap (zebra), are shaded candidates: a band is a row (several baselines may
	// be in one), a baseline row that is in no band is a row of its own, columns from the channels.
	var nb int32 = tbBands(fl, so, bd)
	var i int32 = 0
	var j int32 = 0
	var cnt int32 = 0
	var last int32 = 0
	var ncol int32 = 0
	var gapseen int32 = 0
	var gap1 int32 = 0
	port.CellsDrop(used, 0)
	for i < nb {
		port.CellsPush(used, 0)
		i += 1
	}
	i = 0
	for i < nb {
		if port.CellsAt(used, i) == 0 {
			var sx0 int32 = port.CellsAt(bd, (i*6)+2)
			var sx1 int32 = port.CellsAt(bd, (i*6)+3)
			var colour0 int32 = port.CellsAt(bd, (i*6)+4)
			cnt = 1
			last = i
			ncol = 1
			gapseen = 0
			gap1 = 0
			port.CellsSet(used, i, 2)
			j = i + 1
			for (j < nb) && ((port.CellsAt(bd, j*6) - port.CellsAt(bd, (last*6)+1)) <= 3000) {
				if (port.CellsAt(used, j) == 0) && ((tbAbs(port.CellsAt(bd, (j*6)+2)-sx0) <= 400) && (tbAbs(port.CellsAt(bd, (j*6)+3)-sx1) <= 400)) {
					var g int32 = port.CellsAt(bd, j*6) - port.CellsAt(bd, (last*6)+1)
					var hj int32 = port.CellsAt(bd, (j*6)+1) - port.CellsAt(bd, j*6)
					if (g >= -150) && ((g * 5) <= (hj * 6)) {
						port.CellsSet(used, j, 2)
						cnt += 1
						if g > 150 {
							gapseen = 1
						}
						if (g > 150) && (gap1 == 0) {
							gap1 = g
						}
						if port.CellsAt(bd, (j*6)+4) != colour0 {
							ncol = 2
						}
						last = j
					}
				}
				j += 1
			}
			if (cnt >= 3) && ((ncol == 2) || (gapseen == 1)) {
				var y0 int32 = tbBandHeader(wd, et, w0, w1, sx0, sx1, port.CellsAt(bd, i*6), gap1, wl, rw, sg)
				var y1 int32 = port.CellsAt(bd, (last*6)+1)
				var nr int32 = tbRows(wd, et, w0, w1, sx0, y0, sx1, y1, wl, rw, sg)
				var nt int32 = tbRowsOf(tb, tagtable.Tbs)
				var c0 int32 = tbRowsOf(tc, tcs)
				var wl0 int32 = port.CellsLen(tw)
				var xl0 int32 = port.CellsLen(tx)
				var r int32 = 0
				var trow int32 = -1
				var prevkey int32 = -999999
				var key int32 = 0
				if nr >= 3 {
					port.CellsDrop(rmap, 0)
					for r < nr {
						key = tbBandMember(bd, used, i, last, (port.CellsAt(rw, (r*rws)+6)+port.CellsAt(rw, (r*rws)+7))/2)
						if key < 0 {
							key = (0 - r) - 10
						}
						if key != prevkey {
							trow += 1
							prevkey = key
						}
						port.CellsPush(rmap, trow)
						r += 1
					}
					var t int32 = tbTextGrid(wd, et, wl, rw, sg, rm, kc, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, 0, nr, pfShaded, 800, 1, sx0, y0, sx1, y1)
					if t >= 0 {
						var sc int32 = tbScore(tb, t, wd, et, tc, tw)
						if sc == 0 {
							tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
						} else {
							port.CellsSet(tb, (t*tagtable.Tbs)+6, sc)
						}
					}
				}
			}
			j = i
			for j <= last {
				if port.CellsAt(used, j) == 2 {
					port.CellsSet(used, j, 1)
				}
				j += 1
			}
		}
		i += 1
	}
	return 0
}

func tbTabularBaselineRows(rw *port.Cells, ra int32, rb int32) int32 {
	// How many of the baseline rows ra..rb are cut in two chunks or more.
	var r int32 = ra
	var n int32 = 0
	for r < rb {
		if port.CellsAt(rw, (r*rws)+9) >= 2 {
			n += 1
		}
		r += 1
	}
	return n
}

func tbMedianPitch(rw *port.Cells, ra int32, rb int32, scratch *port.Cells) int32 {
	// The median distance between the baselines of consecutive rows ra..rb (0 for fewer than two). `scratch` is clobbered.
	var r int32 = ra + 1
	port.CellsDrop(scratch, 0)
	for r < rb {
		port.CellsPush(scratch, port.CellsAt(rw, (r*rws)+2)-port.CellsAt(rw, ((r-1)*rws)+2))
		r += 1
	}
	if port.CellsLen(scratch) < 2 {
		return 0
	}
	tbSortNums(scratch)
	return port.CellsAt(scratch, port.CellsLen(scratch)/2)
}

func tbProseRow(tb *port.Cells, k int32, row int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	var first int32 = port.CellsAt(tb, (k*tagtable.Tbs)+9)
	var end int32 = first + port.CellsAt(tb, (k*tagtable.Tbs)+10)
	var c int32 = first
	var filled int32 = 0
	var words int32 = 0
	var low int32 = 0
	for c < end {
		var cb int32 = c * tcs
		var cn int32 = port.CellsAt(tc, cb+9)
		if (port.CellsAt(tc, cb) == row) && (cn > 0) {
			filled += 1
			words = tbMax(words, cn)
			if (cn >= 2) && (tbLowc(port.CellsAt(et, evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, cb+8)), evidence.HdTstart()))) == 1) {
				low += 1
			}
		}
		c += 1
	}
	if ((filled == 1) && (words >= 9)) || ((filled >= 2) && (low == filled)) {
		return 1
	}
	return 0
}

func tbProseEdge(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// D459: 1 for prose at the first row, 2 at the last, 3 at both. The row predicate is also used by bounded trimming.
	var nrows int32 = port.CellsAt(tb, (k*tagtable.Tbs)+7)
	if nrows < 4 {
		return 0
	}
	return tbProseRow(tb, k, 0, wd, et, tc, tw) + (2 * tbProseRow(tb, k, nrows-1, wd, et, tc, tw))
}

func tbHeadReach(rm *port.Cells, rw *port.Cells, sg *port.Cells, a int32, b int32) int32 {
	// P12.2 (smoke review, issue 3: a statement's `December 31,` over its years): the first row of a run whose rows are a..b, taking in the one-chunk rows
	// above it that are headers: a row of one chunk at most 2.4 sizes over the next, with a rule drawn under it between the two that lies under the text (the
	// rule is as wide as the text, and shorter than nine in ten of the run: a rule as wide as the table is its top border, and what is over it a title). At
	// most two rows. Answers the first row.
	var nrl int32 = tbRowsOf(rm, rls)
	var minx int32 = 2000000000
	var maxx int32 = -2000000000
	var r int32 = a
	var n int32 = 0
	var i int32 = 0
	var more int32 = 1
	var found int32 = 0
	i = a
	for i <= b {
		if port.CellsAt(rw, (i*rws)+4) < minx {
			minx = port.CellsAt(rw, (i*rws)+4)
		}
		if port.CellsAt(rw, (i*rws)+5) > maxx {
			maxx = port.CellsAt(rw, (i*rws)+5)
		}
		i += 1
	}
	for (more == 1) && ((r > 0) && (n < 2)) {
		more = 0
		var p int32 = r - 1
		if port.CellsAt(rw, (p*rws)+9) == 1 {
			if (10 * (port.CellsAt(rw, (r*rws)+2) - port.CellsAt(rw, (p*rws)+2))) <= (24 * port.CellsAt(rw, (r*rws)+3)) {
				var tx0 int32 = port.CellsAt(sg, (port.CellsAt(rw, (p*rws)+8)*sgs)+1)
				var tx1 int32 = port.CellsAt(sg, (port.CellsAt(rw, (p*rws)+8)*sgs)+2)
				var ylo int32 = port.CellsAt(rw, (p*rws)+7)
				var yhi int32 = port.CellsAt(rw, (r*rws)+6)
				found = 0
				i = 0
				for i < nrl {
					if port.CellsAt(rm, i*rls) == 0 {
						var pos int32 = port.CellsAt(rm, (i*rls)+1)
						var a0 int32 = port.CellsAt(rm, (i*rls)+2)
						var a1 int32 = port.CellsAt(rm, (i*rls)+3)
						if (pos >= (ylo - 300)) && (pos <= (yhi + 300)) {
							if (a0 <= (tx0 + 300)) && (a1 >= (tx1 - 300)) {
								if (10 * (a1 - a0)) < (9 * (maxx - minx)) {
									found = 1
								}
							}
						}
					}
					i += 1
				}
				if found == 1 {
					r = p
					n += 1
					more = 1
				}
			}
		}
	}
	return r
}

